insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('rest-types-inventory', 'Rest Types Inventory', 'worksheet'::resource_kind, 'Sorts rest into physical, mental, social, sensory and creative kinds so a client can see which kind is missing.', 'Match the kind of rest a client needs to the kind of tiredness they have.', array['Adults', 'Teens']::text[], '20 minutes', 'Many clients equate rest with sleep or screens and stay tired anyway. Ask the client to rate last week kind by kind before filling in the plan, and notice whether the missing kind surprises them. Keep the plan small, one change this week, and review how it went at the next session.', '[{"id": "f0", "type": "textarea", "label": "Last week, when did you feel truly rested, and what kind of rest was it?"}, {"id": "f1", "type": "textarea", "label": "Which of these kinds of rest did you get a little of: physical, mental, social, sensory, creative?"}, {"id": "f2", "type": "textarea", "label": "Which kind is most missing right now?"}, {"id": "f3", "type": "textarea", "label": "What usually gets in the way of that kind of rest?"}, {"id": "f4", "type": "textarea", "label": "One small way to add that kind of rest this week"}, {"id": "f5", "type": "textarea", "label": "When and where it will happen"}, {"id": "f6", "type": "textarea", "label": "How you will know it helped"}]'::jsonb, array['rest', 'burnout', 'routines']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('emotion-vocabulary-ladder', 'Emotion Vocabulary Ladder', 'worksheet'::resource_kind, 'Moves a client from broad words like bad or fine to more precise feeling words, one rung at a time.', 'Build a more precise feeling vocabulary so emotions are easier to name and respond to.', array['Adults', 'Teens']::text[], '20 minutes', 'Start with a recent moment the client called bad, stressed or fine, and climb one rung at a time rather than offering a long word list. Let the client reject words that do not fit; the point is a closer match, not a correct answer. Revisit the ladder when a new strong feeling comes up.', '[{"id": "f0", "type": "textarea", "label": "A recent moment you described as bad, fine or stressed"}, {"id": "f1", "type": "textarea", "label": "The broad word you used for it"}, {"id": "f2", "type": "textarea", "label": "Where you felt it in your body"}, {"id": "f3", "type": "textarea", "label": "A more specific word that fits a little better"}, {"id": "f4", "type": "textarea", "label": "An even closer word, or two words that fit together"}, {"id": "f5", "type": "textarea", "label": "What this feeling might be telling you it wants or needs"}, {"id": "f6", "type": "textarea", "label": "One small thing that would respond to it"}]'::jsonb, array['emotion regulation', 'emotional awareness', 'psychoeducation']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('work-to-home-transition-ritual-planner', 'Work-to-Home Transition Ritual Planner', 'worksheet'::resource_kind, 'Designs a short ritual that marks the end of work so the evening is not spent still half at the desk.', 'Create a clear boundary between work and home with a small, repeatable ritual.', array['Adults']::text[], '20 minutes', 'This suits clients who work from home or carry work worries into the evening. Help them choose a ritual they can do in under ten minutes and that uses a physical cue such as a walk, a change of clothes or closing a notebook. Expect the first few tries to feel awkward and plan a check-in on it.', '[{"id": "f0", "type": "textarea", "label": "How work follows you into the evening right now"}, {"id": "f1", "type": "textarea", "label": "What usually happens in the first hour after you stop working"}, {"id": "f2", "type": "textarea", "label": "Open loops from today you could write down and park"}, {"id": "f3", "type": "textarea", "label": "A cue that could mark the end of work, such as a walk or a change of clothes"}, {"id": "f4", "type": "textarea", "label": "Your ritual in three small steps"}, {"id": "f5", "type": "textarea", "label": "What you want to be present for after the ritual"}, {"id": "f6", "type": "textarea", "label": "What might get in the way, and your plan for it"}]'::jsonb, array['work', 'boundaries', 'routines']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('asking-for-help-ledger', 'Asking for Help Ledger', 'worksheet'::resource_kind, 'Tracks small requests for help, what the client predicted and what actually happened.', 'Test the client''s predictions about asking for help with small, real requests.', array['Adults', 'Teens']::text[], 'One week', 'Useful for clients who carry things alone or expect to be a burden. Agree on two or three small, low-stakes requests in session and have the client write the prediction before each one. Review the gap between predicted and actual responses together, and honor any request that did not go well without rushing to reassure.', '[{"id": "f0", "type": "textarea", "label": "A small request you could make this week"}, {"id": "f1", "type": "textarea", "label": "Who you would ask"}, {"id": "f2", "type": "textarea", "label": "What you predict will happen, and how sure you are"}, {"id": "f3", "type": "textarea", "label": "What you actually asked, and when"}, {"id": "f4", "type": "textarea", "label": "What happened, including how the other person responded"}, {"id": "f5", "type": "textarea", "label": "How it felt afterward"}, {"id": "f6", "type": "textarea", "label": "What this tells you about asking next time"}]'::jsonb, array['support', 'assertiveness', 'self-monitoring']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('life-transition-preparation-sheet', 'Life Transition Preparation Sheet', 'worksheet'::resource_kind, 'Maps what is ending, what is starting and what stays steady during a move, job change, breakup or other transition.', 'Help a client prepare for a life change by naming losses, hopes and anchors.', array['Adults', 'Teens']::text[], '30 minutes', 'Transitions bring mixed feelings, and clients often feel they should only be excited or only be sad. Make space for both columns before moving to planning. The anchors question is often the most useful, since routines and people who stay constant can steady the first weeks. Revisit it after the change begins.', '[{"id": "f0", "type": "textarea", "label": "The change you are going through or approaching"}, {"id": "f1", "type": "textarea", "label": "What is ending or being left behind"}, {"id": "f2", "type": "textarea", "label": "What is starting or might be gained"}, {"id": "f3", "type": "textarea", "label": "Feelings you notice about it, including mixed ones"}, {"id": "f4", "type": "textarea", "label": "Routines, people and places that will stay steady"}, {"id": "f5", "type": "textarea", "label": "One thing you want to prepare before the change"}, {"id": "f6", "type": "textarea", "label": "Who you want to tell about how it is going"}, {"id": "f7", "type": "textarea", "label": "What you will do in the first two weeks to look after yourself"}]'::jsonb, array['transitions', 'life review', 'planning']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('friend-standard-flip-sheet', 'Friend Standard Flip Sheet', 'cbt'::resource_kind, 'A side-by-side page comparing what a client says to themselves with what they would say to a friend.', 'Expose a harsher inner standard and practice a fairer, more balanced voice.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick a situation where your client is clearly hard on themselves. Have them fill in the friend column first, since it usually comes easily, then read both aloud. Watch for ''but that''s different''; gently ask what makes it different, and let them draft one sentence they could believe.', '[{"id": "f0", "type": "textarea", "label": "The situation, in one or two sentences"}, {"id": "f1", "type": "textarea", "label": "What I say to myself about it"}, {"id": "f2", "type": "textarea", "label": "If a close friend were in the same spot, what I would say to them"}, {"id": "f3", "type": "textarea", "label": "What is different between those two voices"}, {"id": "f4", "type": "textarea", "label": "Which voice feels kinder, and which feels more accurate"}, {"id": "f5", "type": "textarea", "label": "One sentence from the friend voice I could try this week"}]'::jsonb, array['self-criticism', 'thinking traps', 'core CBT']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('graded-task-assignment-ladder', 'Graded Task Assignment Ladder', 'cbt'::resource_kind, 'A ladder that breaks a task a client has been avoiding into small, doable rungs with predictions and outcomes.', 'Rebuild momentum on a stalled task by starting small and checking predictions against results.', array['Adults', 'Teens']::text[], 'Full session, then one week', 'Choose a task that feels too big, such as a pile of mail or a phone call. Help your client cut it into rungs they would rate as very doable, and have them predict difficulty before each one. Review mismatches next session; finishing a rung counts even if it is small.', '[{"id": "f0", "type": "textarea", "label": "The task I have been putting off"}, {"id": "f1", "type": "textarea", "label": "Why it feels too big right now"}, {"id": "f2", "type": "textarea", "label": "Rung 1: the smallest first step"}, {"id": "f3", "type": "textarea", "label": "Rung 2: a slightly bigger step"}, {"id": "f4", "type": "textarea", "label": "Rung 3: a bigger step still"}, {"id": "f5", "type": "textarea", "label": "Rung 4 and beyond: the rest of the task"}, {"id": "f6", "type": "textarea", "label": "How hard I predicted each rung would be (0-10)"}, {"id": "f7", "type": "textarea", "label": "How hard each rung actually was (0-10)"}, {"id": "f8", "type": "textarea", "label": "What I noticed when I finished a rung"}]'::jsonb, array['behavioral activation', 'depression', 'scheduling']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('problem-solving-six-steps-sheet', 'Problem-Solving Six Steps Sheet', 'cbt'::resource_kind, 'A step-by-step page for naming a problem, brainstorming options, weighing them, and trying one.', 'Move a client from feeling stuck to choosing and testing one concrete solution.', array['Adults', 'Teens', 'Couples']::text[], '30 minutes', 'Use a problem that has a real action available, not a worry about something out of reach. Encourage wild options in the brainstorm step and hold judgment until the weighing step. If your client skips the review step, bring it back in session so a partial result still teaches something.', '[{"id": "f0", "type": "textarea", "label": "The problem, stated in one specific sentence"}, {"id": "f1", "type": "textarea", "label": "What I want to be different"}, {"id": "f2", "type": "textarea", "label": "Every option I can think of, even silly ones"}, {"id": "f3", "type": "textarea", "label": "Pros and cons of my top three options"}, {"id": "f4", "type": "textarea", "label": "The option I will try"}, {"id": "f5", "type": "textarea", "label": "Exactly what I will do, when, and with whom"}, {"id": "f6", "type": "textarea", "label": "What happened when I tried it"}, {"id": "f7", "type": "textarea", "label": "What I would keep, change, or try next"}]'::jsonb, array['problem solving', 'coping skills', 'core CBT']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('emotional-reasoning-check', 'Emotional Reasoning Check', 'cbt'::resource_kind, 'A worksheet for separating a strong feeling from the facts about the situation that set it off.', 'Help a client notice when a feeling is being treated as proof, and look at the facts too.', array['Adults', 'Teens']::text[], '15 minutes', 'Start with a moment when your client said something like ''I feel stupid, so I must be.'' Make clear that feelings are real and worth respecting; the question is whether the feeling tells us everything about the situation. Revisit the facts column together before assigning it for the week.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "The feeling and how strong it was (0-100)"}, {"id": "f2", "type": "textarea", "label": "The ''I feel ___, so it must be ___'' thought"}, {"id": "f3", "type": "textarea", "label": "Facts that fit that thought"}, {"id": "f4", "type": "textarea", "label": "Facts that do not fit that thought"}, {"id": "f5", "type": "textarea", "label": "How a neutral observer would describe what happened"}, {"id": "f6", "type": "textarea", "label": "How strong the feeling is after looking at the facts (0-100)"}]'::jsonb, array['thinking traps', 'emotional reasoning', 'core CBT']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('sleep-thoughts-and-night-log', 'Sleep Thoughts and Night Log', 'cbt'::resource_kind, 'A bedtime and morning log of racing thoughts, sleep beliefs, and how the night actually went.', 'Show how thoughts about sleep and the night''s real pattern relate, using a week of data.', array['Adults', 'Teens']::text[], 'One week', 'Ask your client to fill in the evening section before bed and the morning section within an hour of waking, without checking the clock during the night. Look for beliefs like ''I cannot function without eight hours'' and compare them with the next day''s notes. Medical questions about sleep belong with your client''s physician.', '[{"id": "f0", "type": "textarea", "label": "Time I got into bed and what I did in the hour before"}, {"id": "f1", "type": "textarea", "label": "Thoughts that showed up as I tried to sleep"}, {"id": "f2", "type": "textarea", "label": "How much I believed each thought (0-100)"}, {"id": "f3", "type": "textarea", "label": "What I did when I could not sleep"}, {"id": "f4", "type": "textarea", "label": "My best guess of how long it took to fall asleep"}, {"id": "f5", "type": "textarea", "label": "How I felt the next morning (0-10)"}, {"id": "f6", "type": "textarea", "label": "How the day actually went compared to what I feared"}, {"id": "f7", "type": "textarea", "label": "A more balanced thought about sleep for tonight"}]'::jsonb, array['sleep', 'thinking traps', 'monitoring']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('hexaflex-snapshot', 'Hexaflex Snapshot', 'act'::resource_kind, 'A one-page check of six flexibility processes, each rated and paired with one small next move.', 'Show the client and clinician where flexibility is strong and where to focus next.', array['Adults', 'Teens']::text[], '30 minutes', 'Walk the six processes in plain language rather than jargon, and let the client rate each one from their own experience instead of offering your view. The ratings are a conversation starter, not a score. Pick one low-rated area together and keep the next move small. Revisit every few weeks to see what has shifted.', '[{"id": "f0", "type": "textarea", "label": "Present moment: how much am I here, and how much am I elsewhere?"}, {"id": "f1", "type": "textarea", "label": "Acceptance: how willing am I to let hard feelings be there?"}, {"id": "f2", "type": "textarea", "label": "Defusion: how tightly do my thoughts grab me?"}, {"id": "f3", "type": "textarea", "label": "Self as context: can I notice my thoughts and feelings from a step back?"}, {"id": "f4", "type": "textarea", "label": "Values: how clear am I about what matters to me?"}, {"id": "f5", "type": "textarea", "label": "Committed action: how often do my actions follow my values?"}, {"id": "f6", "type": "textarea", "label": "Which one area do I want to work on first?"}, {"id": "f7", "type": "textarea", "label": "One small move I will try this week"}]'::jsonb, array['core ACT', 'review', 'flexibility']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('hands-as-thoughts-exercise', 'Hands as Thoughts Exercise', 'act'::resource_kind, 'A physical demonstration of how holding thoughts tightly crowds out the world, then loosening the grip.', 'Let the client feel the difference between being fused with thoughts and holding them lightly.', array['Adults', 'Teens', 'Groups']::text[], '15 minutes', 'Ask the client to cup both hands and press them against their face as if the hands were their thoughts, then describe what they can and cannot do. Next, lower the hands into the lap and notice what returns. Go slowly and use their own words for the thoughts. Some clients find it silly at first, which is fine and often useful.', '[{"id": "f0", "type": "textarea", "label": "What thought did I let my hands stand for?"}, {"id": "f1", "type": "textarea", "label": "What was it like with my hands pressed to my face?"}, {"id": "f2", "type": "textarea", "label": "What could I not do or notice that way?"}, {"id": "f3", "type": "textarea", "label": "What changed when I lowered my hands to my lap?"}, {"id": "f4", "type": "textarea", "label": "Did the thought go away, or did my relationship to it change?"}, {"id": "f5", "type": "textarea", "label": "Where this week could I hold a thought in my lap instead of at my face?"}]'::jsonb, array['defusion', 'metaphor', 'core ACT']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('values-and-goals-two-column-sort', 'Values and Goals Two-Column Sort', 'act'::resource_kind, 'Sorts a client''s wants into ongoing directions (values) and finishable targets (goals).', 'Help the client tell a direction worth living by from a target that can be checked off.', array['Adults', 'Teens']::text[], '25 minutes', 'Use the compass and destination image: a value is the direction you keep traveling, a goal is a place you can arrive. Clients often list goals when asked about values, so expect to sort together. Once sorted, link each goal back to the value it serves, and notice any goal that serves no value at all. Keep your own preferences out of the sorting.', '[{"id": "f0", "type": "textarea", "label": "Things I want in my life right now (list freely)"}, {"id": "f1", "type": "textarea", "label": "Which of these can be finished or checked off? (goals)"}, {"id": "f2", "type": "textarea", "label": "Which are ongoing ways I want to act or be? (values)"}, {"id": "f3", "type": "textarea", "label": "For one goal, the value it serves"}, {"id": "f4", "type": "textarea", "label": "A goal I have that does not seem to serve any value"}, {"id": "f5", "type": "textarea", "label": "One value I can act on today, whether or not any goal moves"}, {"id": "f6", "type": "textarea", "label": "How does it feel to act on a value without needing a finish line?"}]'::jsonb, array['values', 'clarification', 'goal setting']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('naming-the-old-story', 'Naming the Old Story', 'act'::resource_kind, 'Gives a recurring life story a title so the client can notice it appearing and choose a response.', 'Help the client see a repeating story as a story, and respond with values rather than habit.', array['Adults', 'Teens']::text[], '25 minutes', 'Invite the client to name the story the way they might title a book, such as the I Always Fail story, and keep the title short and a little playful. The point is not to argue that the story is false but to notice when it shows up and what it pulls them toward. Do not rush a client who finds the story painful. Stay curious about what it protects.', '[{"id": "f0", "type": "textarea", "label": "The story my mind tells again and again"}, {"id": "f1", "type": "textarea", "label": "A short title for it, like a book or film"}, {"id": "f2", "type": "textarea", "label": "When it tends to show up"}, {"id": "f3", "type": "textarea", "label": "What it tells me to do, or not do"}, {"id": "f4", "type": "textarea", "label": "What I usually do when it appears"}, {"id": "f5", "type": "textarea", "label": "What that costs me or my values"}, {"id": "f6", "type": "textarea", "label": "What I could say to my mind when I notice it: Ah, the old story again"}, {"id": "f7", "type": "textarea", "label": "One thing I could do this week with the story present"}]'::jsonb, array['defusion', 'narrative', 'core ACT']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('control-strategies-inventory', 'Control Strategies Inventory', 'act'::resource_kind, 'Lists what the client has tried to control or avoid a feeling, and what each try gave and cost.', 'Let the client see for themselves how well control strategies have worked over time.', array['Adults', 'Teens']::text[], '30 minutes', 'Draw out the full list without judgment, including strategies that look healthy. For each, ask what it did in the short run and over months. Let the client reach the conclusion about workability rather than telling them. Expect some sadness when the costs add up, so leave time to close with values and what they would like to do instead. If hopeless thoughts about life arise, stay with the client in session and follow your own risk steps.', '[{"id": "f0", "type": "textarea", "label": "The feeling or thought I have been trying to get rid of"}, {"id": "f1", "type": "textarea", "label": "Things I have tried to make it go away"}, {"id": "f2", "type": "textarea", "label": "What each one did for me in the short run"}, {"id": "f3", "type": "textarea", "label": "What each one has cost me over weeks and months"}, {"id": "f4", "type": "textarea", "label": "Has the feeling actually gone away for good?"}, {"id": "f5", "type": "textarea", "label": "What would I be doing if I did not have to win this fight?"}, {"id": "f6", "type": "textarea", "label": "If 988 (call or text) is ever needed, the one person I would tell first: complete this in session"}]'::jsonb, array['struggle', 'workability', 'avoidance']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('improve-skills-pocket-card', 'IMPROVE Skills Pocket Card', 'dbt'::resource_kind, 'A card for picking one IMPROVE skill to get through a painful moment without making it worse.', 'Practice choosing a fitting IMPROVE skill before the hard moment arrives.', array['Adults', 'Teens']::text[], '20 minutes', 'Have your client pick the moment first, then browse imagery, meaning, prayer, relaxation, one thing in the moment, vacation and encouragement. Clients often choose the same skill every time, so ask which one they would try that they never have. Rehearse one choice in session and note what it felt like in the body.', '[{"id": "f0", "type": "textarea", "label": "A painful moment I expect this week"}, {"id": "f1", "type": "textarea", "label": "Imagery: a safe or calming scene I could picture"}, {"id": "f2", "type": "textarea", "label": "Meaning: something I can find worthwhile in this situation"}, {"id": "f3", "type": "textarea", "label": "Relaxation: one way I can loosen my body"}, {"id": "f4", "type": "textarea", "label": "One thing in the moment: what I will focus on fully"}, {"id": "f5", "type": "textarea", "label": "A brief vacation: a short, healthy break I can take"}, {"id": "f6", "type": "textarea", "label": "Encouragement: what I will say to myself"}, {"id": "f7", "type": "textarea", "label": "The skill I will try first, and when"}]'::jsonb, array['distress tolerance', 'IMPROVE', 'skills']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('current-emotion-noticing-log', 'Current Emotion Noticing Log', 'dbt'::resource_kind, 'A short log for noticing an emotion as a wave, naming it, and letting it pass without acting on it.', 'Build the habit of observing an emotion without pushing it away or feeding it.', array['Adults', 'Teens']::text[], 'Five minutes, several times a week', 'Introduce this after your client can name basic emotions. The aim is to watch the emotion rise and fall, not to change it. Watch for clients who describe the story instead of the sensations; gently bring them back to the body. Review two or three entries together and ask what changed once they stopped fighting the feeling.', '[{"id": "f0", "type": "textarea", "label": "The emotion I noticed and what set it off"}, {"id": "f1", "type": "textarea", "label": "Where I felt it in my body"}, {"id": "f2", "type": "textarea", "label": "How strong it was at its peak, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What the urge was"}, {"id": "f4", "type": "textarea", "label": "What I did instead of acting on it"}, {"id": "f5", "type": "textarea", "label": "How I reminded myself that emotions come and go"}, {"id": "f6", "type": "textarea", "label": "How strong it was five minutes later, 0 to 10"}, {"id": "f7", "type": "textarea", "label": "What I noticed about watching it"}]'::jsonb, array['mindfulness', 'emotion regulation', 'urges']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('turning-the-mind-commitment-card', 'Turning the Mind Commitment Card', 'dbt'::resource_kind, 'A card for noticing when the mind has turned away from acceptance and choosing to turn it back.', 'Recognize the moment of refusing reality and practice turning toward acceptance.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients often describe turning the mind as a single decision, but it is usually a choice they must make again and again. Ask for a specific situation where they are stuck in refusal or sulking. Help them find the early signs, and keep the commitment small enough to repeat today.', '[{"id": "f0", "type": "textarea", "label": "A situation I am fighting right now"}, {"id": "f1", "type": "textarea", "label": "How I know I have turned away from accepting it"}, {"id": "f2", "type": "textarea", "label": "What my body does when I refuse it"}, {"id": "f3", "type": "textarea", "label": "What I tell myself in those moments"}, {"id": "f4", "type": "textarea", "label": "What turning my mind back would look like"}, {"id": "f5", "type": "textarea", "label": "One small action that shows I have turned"}, {"id": "f6", "type": "textarea", "label": "A reminder I can put where I will see it"}, {"id": "f7", "type": "textarea", "label": "What might get in the way, and how I will start again"}]'::jsonb, array['radical acceptance', 'acceptance', 'willingness']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('emotion-problem-solving-steps', 'Emotion Problem-Solving Steps', 'dbt'::resource_kind, 'A step-by-step page for deciding whether to change a situation or change how the feeling is handled.', 'Sort a stuck problem into what can be solved and what must be tolerated.', array['Adults', 'Teens']::text[], '30 minutes', 'Use this when a client keeps replaying one problem. The first step is deciding together whether the situation is solvable now; if it is not, point toward acceptance or soothing skills. Ask your client to brainstorm freely before judging options, since clients often cross off ideas too early.', '[{"id": "f0", "type": "textarea", "label": "The problem, described in observable facts"}, {"id": "f1", "type": "textarea", "label": "What I want to be different"}, {"id": "f2", "type": "textarea", "label": "Is this solvable right now? Why or why not"}, {"id": "f3", "type": "textarea", "label": "Three or more possible solutions, even odd ones"}, {"id": "f4", "type": "textarea", "label": "The pros and cons of my top two choices"}, {"id": "f5", "type": "textarea", "label": "The option I will try first"}, {"id": "f6", "type": "textarea", "label": "The first step and when I will take it"}, {"id": "f7", "type": "textarea", "label": "How I will tell whether it helped"}]'::jsonb, array['problem solving', 'emotion regulation', 'skills']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('one-mindfully-practice-sheet', 'One-Mindfully Practice Sheet', 'dbt'::resource_kind, 'A weekly sheet for doing one ordinary activity with full attention and noting when attention drifts.', 'Strengthen the skill of doing one thing at a time and returning when attention wanders.', array['Adults', 'Teens', 'Groups']::text[], 'One week', 'Clients commonly multitask and then judge themselves harshly when focus slips. Choose a plain activity such as washing dishes or walking, and coach them to count each return of attention as success. Review what pulled them away and any urges that came with it.', '[{"id": "f0", "type": "textarea", "label": "The one activity I chose this week"}, {"id": "f1", "type": "textarea", "label": "Where I did it and for how long"}, {"id": "f2", "type": "textarea", "label": "What I noticed through my senses"}, {"id": "f3", "type": "textarea", "label": "What pulled my attention away"}, {"id": "f4", "type": "textarea", "label": "How I brought it back, without judging myself"}, {"id": "f5", "type": "textarea", "label": "What I noticed in my body or mood afterward"}, {"id": "f6", "type": "textarea", "label": "Where else I could try doing one thing at a time"}, {"id": "f7", "type": "textarea", "label": "What I want to bring to next session"}]'::jsonb, array['mindfulness', 'one-mindfully', 'skills']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('roommate-drift-inventory', 'Roommate Drift Inventory', 'couples'::resource_kind, 'Lists where the couple''s days run in parallel and where they still touch.', 'Show the couple where connection has thinned so they can choose one place to rebuild.', array['Couples']::text[], '30 minutes', 'Useful when a couple says nothing is wrong but nothing is close either. Each partner fills in their own column first, then they compare. Keep the tone curious, not accusing. Let them pick one small place to rebuild, since a long list of fixes tends to feel like another chore.', '[{"id": "f0", "type": "textarea", "label": "Parts of our day we spend in the same room"}, {"id": "f1", "type": "textarea", "label": "Parts of our day we spend apart without choosing to"}, {"id": "f2", "type": "textarea", "label": "Something we used to do together that faded"}, {"id": "f3", "type": "textarea", "label": "What I do that may keep us in separate lanes"}, {"id": "f4", "type": "textarea", "label": "What I miss most about how we used to be"}, {"id": "f5", "type": "textarea", "label": "One small place I would like us to touch each day"}, {"id": "f6", "type": "textarea", "label": "What I am willing to do this week toward that"}, {"id": "f7", "type": "textarea", "label": "What would tell us it is working"}]'::jsonb, array['connection', 'routines', 'relationship issues']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('yes-no-maybe-request-sheet', 'Yes, No, and Maybe Request Sheet', 'couples'::resource_kind, 'Each partner sorts the other''s requests into yes, no and maybe, with a reason for each.', 'Practice making and answering requests without it turning into a verdict on the relationship.', array['Couples']::text[], '45 minutes', 'Have each partner bring three requests. The listener answers yes, no or maybe, and a maybe must name what would make it a yes. Watch for a no that is heard as rejection of the person; slow down and have the speaker reflect what was said. Partners often discover that maybe is the most useful answer.', '[{"id": "f0", "type": "textarea", "label": "A request I am making of my partner"}, {"id": "f1", "type": "textarea", "label": "Why this matters to me"}, {"id": "f2", "type": "textarea", "label": "How I answered my partner''s request (yes, no or maybe)"}, {"id": "f3", "type": "textarea", "label": "What I need to hear to say yes to a maybe"}, {"id": "f4", "type": "textarea", "label": "How it felt to hear a no from my partner"}, {"id": "f5", "type": "textarea", "label": "How it felt to say a no to my partner"}, {"id": "f6", "type": "textarea", "label": "A request we both said yes to"}, {"id": "f7", "type": "textarea", "label": "What I will do differently when I make the next request"}]'::jsonb, array['communication', 'needs', 'boundaries']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('speaker-listener-floor-practice', 'Speaker-Listener Floor Practice', 'couples'::resource_kind, 'A turn-taking script where one partner holds the floor and the other reflects before replying.', 'Slow a hot topic down so each partner is heard before anyone responds.', array['Couples']::text[], 'Full session', 'Use a small object as the floor. The speaker shares a few sentences, the listener paraphrases and asks if they got it right, and only then do roles switch. Begin with a low-stakes topic, then move to a real one. Partners often rush the paraphrase or sneak in a rebuttal; gently stop that and coach it in the moment.', '[{"id": "f0", "type": "textarea", "label": "The topic I will speak about"}, {"id": "f1", "type": "textarea", "label": "My point in one or two short sentences"}, {"id": "f2", "type": "textarea", "label": "What I heard my partner say, in my own words"}, {"id": "f3", "type": "textarea", "label": "What my partner said I missed or got wrong"}, {"id": "f4", "type": "textarea", "label": "What I most needed my partner to understand"}, {"id": "f5", "type": "textarea", "label": "What I felt in my body as I waited my turn"}, {"id": "f6", "type": "textarea", "label": "What helped me stay in the listener role"}, {"id": "f7", "type": "textarea", "label": "What we want to try again next time"}]'::jsonb, array['communication', 'conflict', 'listening']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('social-energy-negotiation-sheet', 'Social Energy Negotiation Sheet', 'couples'::resource_kind, 'Maps each partner''s need for company and quiet and plans a week that fits both.', 'Help the couple talk about differing social energy without treating either need as a flaw.', array['Couples']::text[], '30 minutes', 'Partners often read a difference in social energy as a statement about the relationship. Name the difference as a preference that each of them has, then work through the week together. Look for trades that are specific, such as one night out and one night in, rather than broad promises.', '[{"id": "f0", "type": "textarea", "label": "What kinds of company give me energy"}, {"id": "f1", "type": "textarea", "label": "What kinds of company drain me"}, {"id": "f2", "type": "textarea", "label": "How much time alone I need in a typical week"}, {"id": "f3", "type": "textarea", "label": "How I usually tell my partner when I need space"}, {"id": "f4", "type": "textarea", "label": "How I usually tell my partner when I want company"}, {"id": "f5", "type": "textarea", "label": "Plans this month that I am looking forward to or dreading"}, {"id": "f6", "type": "textarea", "label": "A trade I could offer my partner this week"}, {"id": "f7", "type": "textarea", "label": "How we will check in when the plan is not working"}]'::jsonb, array['boundaries', 'needs', 'communication']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('reassurance-request-card', 'Reassurance Request Card', 'couples'::resource_kind, 'Helps one partner ask for reassurance in a clear way and the other decide what they can offer.', 'Move from hints and tests to direct requests for reassurance that both partners can carry out.', array['Couples']::text[], '30 minutes', 'Suited to couples where one partner seeks closeness through checking or hinting and the other pulls back. Have both complete the card, and let the reassuring partner say what is realistic to offer. Be alert to reassurance that has become endless; agree on a few specific gestures rather than unlimited answers.', '[{"id": "f0", "type": "textarea", "label": "A moment lately when I wanted reassurance"}, {"id": "f1", "type": "textarea", "label": "What I did or said at the time"}, {"id": "f2", "type": "textarea", "label": "What I actually wanted to hear or feel"}, {"id": "f3", "type": "textarea", "label": "A clear way I could ask for it next time"}, {"id": "f4", "type": "textarea", "label": "What my partner can realistically offer"}, {"id": "f5", "type": "textarea", "label": "What my partner cannot offer, and what I can do for myself then"}, {"id": "f6", "type": "textarea", "label": "A signal we will use when I need a moment of reassurance"}, {"id": "f7", "type": "textarea", "label": "How we will tell whether this is helping"}]'::jsonb, array['trust', 'connection', 'communication']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('calm-down-glitter-jar-craft', 'Calm-Down Glitter Jar Craft', 'kids'::resource_kind, 'The child builds a sealed jar of water and glitter to shake, watch settle and name as their mind calming.', 'Give a child a visual, hands-on picture of big feelings settling when they pause.', array['Children']::text[], '25 minutes', 'Let the child pour, stir and seal the jar, then shake it together and narrate the swirl as a busy mind. Ask the parent to keep a copy at home and to sit beside the child while it settles rather than telling them to calm down. If a child discloses something worrying while you build, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "What color glitter did I pick for my big feeling?"}, {"id": "f1", "type": "textarea", "label": "What does the swirl look like to me?"}, {"id": "f2", "type": "textarea", "label": "What happens to the glitter when I sit still?"}, {"id": "f3", "type": "textarea", "label": "What do I notice in my body as it settles?"}, {"id": "f4", "type": "textarea", "label": "When could I use my jar at home?"}, {"id": "f5", "type": "textarea", "label": "How will my grown-up help me use it?"}]'::jsonb, array['children', 'play', 'regulation']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('hello-and-goodbye-ritual-card', 'Hello and Goodbye Ritual Card', 'kids'::resource_kind, 'The child and parent draw a short goodbye and reunion routine on a card the child can keep.', 'Make drop-offs predictable with a drawn, practiced routine the child helps design.', array['Children', 'Adults']::text[], '25 minutes', 'Have the child draw each step of a quick goodbye: a hug, a special wave, a phrase, then the parent leaving. The parent practices it in the room, keeping it short and warm and following through on the plan. Note what the parent does when the child protests. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw our goodbye hug or wave."}, {"id": "f1", "type": "textarea", "label": "What special words do we say?"}, {"id": "f2", "type": "textarea", "label": "Draw what I can do after my grown-up leaves."}, {"id": "f3", "type": "textarea", "label": "Where does my grown-up go, and what will they do?"}, {"id": "f4", "type": "textarea", "label": "Draw our hello when we are back together."}, {"id": "f5", "type": "textarea", "label": "What small thing can I hold to feel close?"}]'::jsonb, array['children', 'routines', 'parenting', 'transitions']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('friendship-ingredients-recipe-card', 'Friendship Ingredients Recipe Card', 'kids'::resource_kind, 'The child draws a recipe card listing the ingredients of being a good friend and how to mix them.', 'Help a child picture concrete friendship moves they can try at school or play.', array['Children']::text[], '25 minutes', 'Frame it as a pretend cooking show, with ingredients such as sharing, asking, and listening. Let the child draw each one and act out a mini scene with you. Ask the parent to try one ingredient at home that week and name it when they see it. If a child discloses mistreatment by peers or adults, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "The name of my friendship recipe"}, {"id": "f1", "type": "textarea", "label": "Ingredient one: something I can say or do"}, {"id": "f2", "type": "textarea", "label": "Ingredient two: something I can share or ask"}, {"id": "f3", "type": "textarea", "label": "Ingredient three: how I can listen"}, {"id": "f4", "type": "textarea", "label": "What happens if the recipe gets a little burnt?"}, {"id": "f5", "type": "textarea", "label": "Who will I try my recipe with this week?"}]'::jsonb, array['children', 'social skills', 'play']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('repair-comic-strip', 'Repair Comic Strip', 'kids'::resource_kind, 'The child draws a four-panel comic of a conflict, a pause, a repair and what happens next.', 'Teach a child that arguments can be repaired and practice what to say afterward.', array['Children', 'Teens']::text[], '30 minutes', 'Choose a small, recent squabble and let the child pick the characters. Draw what happened, the moment of pause, how each character feels, and a repair that fits the child''s own words. Invite the parent or sibling to act the repair out. If a child discloses harm at home, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Panel one: draw what happened."}, {"id": "f1", "type": "textarea", "label": "Panel two: draw how each character felt."}, {"id": "f2", "type": "textarea", "label": "Panel three: draw a pause and a calm choice."}, {"id": "f3", "type": "textarea", "label": "Panel four: draw a way to make it right."}, {"id": "f4", "type": "textarea", "label": "What words could the characters use to repair?"}, {"id": "f5", "type": "textarea", "label": "What will I try next time this happens?"}]'::jsonb, array['children', 'repair', 'conflict', 'art']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('traffic-light-pause-craft', 'Traffic Light Pause Craft', 'kids'::resource_kind, 'The child builds a red, yellow and green paper traffic light that maps stop, think and go.', 'Give a child a handmade cue for pausing before acting on a strong urge.', array['Children']::text[], '25 minutes', 'Build the light from paper circles and a card strip, then practice with low-stakes pretend scenes before real ones. Red is stop and breathe, yellow is think of choices, green is pick one. The parent uses the same colors at home, calmly and out loud. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "What does my body do at red?"}, {"id": "f1", "type": "textarea", "label": "What can I do to stop and breathe?"}, {"id": "f2", "type": "textarea", "label": "What are two choices I could think of at yellow?"}, {"id": "f3", "type": "textarea", "label": "What happens after each choice?"}, {"id": "f4", "type": "textarea", "label": "What is my green go choice?"}, {"id": "f5", "type": "textarea", "label": "Where will I hang my light at home?"}]'::jsonb, array['children', 'play', 'regulation', 'self-talk']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('five-senses-treasure-hunt', 'Five Senses Treasure Hunt', 'game'::resource_kind, 'A timed hunt for objects in the room that match a sense, followed by a quick debrief.', 'Practice anchoring attention in the present by noticing the room through each sense.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Call out a sense and give each player a minute to find something in the room that fits, then take turns naming it. Keep the prompts neutral and about the room only. Let anyone pass or sit out a round, and end by asking which sense settled them most so they can reuse it outside the office.', '[{"id": "f0", "type": "textarea", "label": "Something I found for sight"}, {"id": "f1", "type": "textarea", "label": "Something I found for sound"}, {"id": "f2", "type": "textarea", "label": "Something I found for touch"}, {"id": "f3", "type": "textarea", "label": "The sense that helped me feel most settled"}, {"id": "f4", "type": "textarea", "label": "A place outside this room where I could play this quietly"}]'::jsonb, array['grounding', 'play', 'group']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('kindness-coupon-trade', 'Kindness Coupon Trade', 'game'::resource_kind, 'Players write small self-kindness coupons, trade them, and redeem one during the week.', 'Build a habit of offering ourselves the same small kindnesses we offer others.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Each player writes three coupons for realistic acts of self-kindness, such as a ten minute walk or an early night. Shuffle, deal, and let players trade once if a coupon feels out of reach. Watch for coupons that are really chores or self-criticism in disguise, and ask the group to rewrite them gently.', '[{"id": "f0", "type": "textarea", "label": "Three coupons I wrote"}, {"id": "f1", "type": "textarea", "label": "The coupon I received"}, {"id": "f2", "type": "textarea", "label": "Whether I traded it and why"}, {"id": "f3", "type": "textarea", "label": "When I will redeem it this week"}, {"id": "f4", "type": "textarea", "label": "What got in the way of writing for myself"}]'::jsonb, array['self-compassion', 'group', 'play']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('one-word-story-relay', 'One Word Story Relay', 'game'::resource_kind, 'Players build a story one word at a time, then talk about listening, letting go and surprise.', 'Practice flexibility and shared attention by building on what another person says.', array['Children', 'Teens', 'Groups']::text[], '15 minutes', 'Sit in a circle and build a story one word per turn, with a gentle rule that you may not steer it back to your own idea. Run two rounds, the second with a calm story goal. In the debrief, ask what it felt like when the story went somewhere unexpected and how each player handled it.', '[{"id": "f0", "type": "textarea", "label": "My favorite moment in the story"}, {"id": "f1", "type": "textarea", "label": "A time I wanted to steer the story"}, {"id": "f2", "type": "textarea", "label": "How I felt when it went somewhere unexpected"}, {"id": "f3", "type": "textarea", "label": "What helped me keep listening"}, {"id": "f4", "type": "textarea", "label": "Where else I could try going with it"}]'::jsonb, array['flexibility', 'listening', 'group', 'play']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('red-light-green-light-feelings', 'Red Light Green Light Feelings', 'game'::resource_kind, 'A stop and go game where each color is paired with a body signal and a calming move.', 'Help children notice early body signals and practice pausing before reacting.', array['Children', 'Groups']::text[], '20 minutes', 'Play classic red light, green light, then add a card for each stop naming a feeling and a body signal, such as hot face or tight fists. Children pick a calming move before the next go. Invite the parent to learn the signal words and use the same stop cue at home. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "The feeling I stopped on most"}, {"id": "f1", "type": "textarea", "label": "Where I felt it in my body"}, {"id": "f2", "type": "textarea", "label": "The calming move I picked"}, {"id": "f3", "type": "textarea", "label": "What my grown-up can say to cue me"}, {"id": "f4", "type": "textarea", "label": "When I could use stop at home"}]'::jsonb, array['regulation', 'play', 'children', 'impulse control']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('support-circle-yarn-web', 'Support Circle Yarn Web', 'game'::resource_kind, 'Players toss a ball of yarn to name a support person, building a web they can see.', 'Make a client''s sources of support visible and name how each one helps.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Hold the yarn, name one person or place you can lean on and what they offer, then toss it on while keeping hold of your strand. When the web is done, gently tug and ask what happens when one strand is loose. Let anyone with few supports name a pet, a routine or a hotline, and note gaps for later.', '[{"id": "f0", "type": "textarea", "label": "A support I named and what they offer"}, {"id": "f1", "type": "textarea", "label": "A support I forgot until I saw the web"}, {"id": "f2", "type": "textarea", "label": "Who is missing that I would like to add"}, {"id": "f3", "type": "textarea", "label": "One small step to reach out this week"}, {"id": "f4", "type": "textarea", "label": "What it was like to see the web"}]'::jsonb, array['support', 'connection', 'group', 'play']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('safe-people-and-places-inventory', 'Safe People and Places Inventory', 'worksheet'::resource_kind, 'Lists the people, places and activities that currently feel steady, rated by how safe they feel.', 'Build a shared, concrete picture of present-day sources of safety and support.', array['Adults', 'Teens']::text[], '20 minutes', 'Useful early, when a client needs stabilizing resources more than anything else. Keep it entirely in the present: the sheet asks what feels safe now and never what happened. If a client cannot name many, that is information about where to build support, so note it gently and start with one small entry.', '[{"id": "f0", "type": "textarea", "label": "A person who feels safe to be around, and what they do that helps"}, {"id": "f1", "type": "textarea", "label": "A place where my body can relax a little"}, {"id": "f2", "type": "textarea", "label": "An activity that steadies me"}, {"id": "f3", "type": "textarea", "label": "Rate each of these from 0 to 10 for how safe it feels today"}, {"id": "f4", "type": "textarea", "label": "Something that makes a safe place feel less safe"}, {"id": "f5", "type": "textarea", "label": "One safe person or place I could add this month"}, {"id": "f6", "type": "textarea", "label": "How I can reach one of these when I need it this week"}]'::jsonb, array['PTSD and trauma', 'support', 'safety']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('then-and-now-thought-check', 'Then and Now Thought Check', 'cbt'::resource_kind, 'Sorts thoughts about danger into what feels true in the body and what is true in the present moment.', 'Help a client separate a past-linked alarm from what is happening right now.', array['Adults']::text[], '20 minutes', 'Have the client pick a recent moment when they felt on alert and record only the thought and the setting today, not the original events. The aim is to notice the difference between a body that is sounding an alarm and a present that may be safe enough. Go slowly, and stop to ground if the exercise raises distress.', '[{"id": "f0", "type": "textarea", "label": "Where I was and what was happening around me just now"}, {"id": "f1", "type": "textarea", "label": "The thought that said I was in danger"}, {"id": "f2", "type": "textarea", "label": "How strong the alarm felt in my body, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What I can see, hear and touch right now that tells me about today"}, {"id": "f4", "type": "textarea", "label": "Facts that fit with this moment being safe enough"}, {"id": "f5", "type": "textarea", "label": "A kinder, more balanced thought for next time"}, {"id": "f6", "type": "textarea", "label": "How strong the alarm feels now, 0 to 10"}]'::jsonb, array['PTSD and trauma', 'thinking traps', 'core CBT']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('values-compass-after-hard-times', 'Values Compass for Returning to Life', 'act'::resource_kind, 'Maps what a client has stepped back from, what they care about, and one small step toward each.', 'Reconnect a client with valued living at a pace their body can manage.', array['Adults']::text[], 'Full session', 'Pair this with grounding already in the client''s toolkit. Invite them to name areas of life that have shrunk, then pick one value and one very small step, sized so it can be done even on a hard day. Willingness here means making room for whatever shows up, never pushing into reminders; adjust the pace to the client.', '[{"id": "f0", "type": "textarea", "label": "Areas of life I have stepped back from"}, {"id": "f1", "type": "textarea", "label": "What I care about in one of those areas"}, {"id": "f2", "type": "textarea", "label": "What kind of person I want to be there"}, {"id": "f3", "type": "textarea", "label": "One very small step I could take this week"}, {"id": "f4", "type": "textarea", "label": "Feelings or sensations that may show up when I try it"}, {"id": "f5", "type": "textarea", "label": "What I can do to make room for them and ground myself"}, {"id": "f6", "type": "textarea", "label": "Who could support me with this step"}]'::jsonb, array['PTSD and trauma', 'values', 'core ACT']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('tipp-body-reset-plan', 'TIPP Body Reset Plan', 'dbt'::resource_kind, 'Plans which TIPP skill (temperature, intense exercise, paced breathing, paired muscle relaxation) fits which surge.', 'Give a client a body-first reset to try when distress climbs fast.', array['Adults', 'Teens']::text[], '25 minutes', 'Walk through each TIPP skill in session and let the client try the ones that feel tolerable. Ask about health or medical limits before suggesting temperature change or intense exercise, and skip any step that feels unsafe or too activating. Aim for a short written plan the client can keep on a phone or card.', '[{"id": "f0", "type": "textarea", "label": "How my body feels when distress is rising fast"}, {"id": "f1", "type": "textarea", "label": "Temperature: what cool option I could use, and how it felt"}, {"id": "f2", "type": "textarea", "label": "Intense exercise: a short movement I could do, if my body allows"}, {"id": "f3", "type": "textarea", "label": "Paced breathing: how long I breathe in and out, and how it felt"}, {"id": "f4", "type": "textarea", "label": "Paired muscle relaxation: where I tense and release"}, {"id": "f5", "type": "textarea", "label": "Which of these helped most, and which I will skip"}, {"id": "f6", "type": "textarea", "label": "My distress before and after, 0 to 10"}, {"id": "f7", "type": "textarea", "label": "Where I will keep this plan so I can find it quickly"}]'::jsonb, array['PTSD and trauma', 'distress tolerance', 'regulation']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('partner-pacing-agreement-for-hard-topics', 'Partner Pacing Agreement', 'couples'::resource_kind, 'Sets how a couple will pause, pace and return to hard topics without either partner being pushed.', 'Help both partners agree on signals and limits that keep closeness steady around trauma reminders.', array['Couples']::text[], 'Full session', 'Each partner fills in their own part. The partner with the trauma history names what helps, what a pause looks like and how much they want to share; the other partner names what they can offer, what they need for themselves and how they will check in. Nothing here requires details of past events, and either partner can say stop.', '[{"id": "f0", "type": "textarea", "label": "Partner A: topics I am not ready to go into yet"}, {"id": "f1", "type": "textarea", "label": "Partner A: the signal I will use to ask for a pause"}, {"id": "f2", "type": "textarea", "label": "Partner A: what helps me come back to the present"}, {"id": "f3", "type": "textarea", "label": "Partner B: how I will respond when I see the pause signal"}, {"id": "f4", "type": "textarea", "label": "Partner B: what I need so I do not feel shut out"}, {"id": "f5", "type": "textarea", "label": "Partner B: a way I take care of myself during a pause"}, {"id": "f6", "type": "textarea", "label": "Together: how long a pause lasts and who restarts the talk"}, {"id": "f7", "type": "textarea", "label": "Together: one thing we will do afterward to reconnect"}]'::jsonb, array['PTSD and trauma', 'couples', 'support', 'connection']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('anxiety-weather-report-drawing', 'Anxiety Weather Report Drawing', 'kids'::resource_kind, 'A child draws the weather inside their body, from sunny to stormy, and plans what helps each kind.', 'Give a child a playful way to name how big a worry feels and what helps.', array['Children']::text[], '20 minutes', 'Hand over paper and colors and let the child draw a weather scene for today, then a sunny, cloudy and stormy version. Ask the parent to join for the last few minutes so they can learn the words the child uses and what the parent does when it turns stormy. If a child discloses harm or abuse, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw the weather inside you today"}, {"id": "f1", "type": "textarea", "label": "Draw what a sunny feeling looks like"}, {"id": "f2", "type": "textarea", "label": "Draw what a stormy feeling looks like"}, {"id": "f3", "type": "textarea", "label": "What happens in my body when a storm comes"}, {"id": "f4", "type": "textarea", "label": "Something that helps a storm pass, drawn or written"}, {"id": "f5", "type": "textarea", "label": "What a grown-up can do to help when it is stormy"}]'::jsonb, array['anxiety', 'children', 'art', 'regulation']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('prediction-check-game', 'Prediction Check Game', 'game'::resource_kind, 'Players predict how a feared situation will go, try it, and score the gap between guess and outcome.', 'Let a client see how often predictions about anxious situations are off, through play.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Players take turns drawing a small, safe challenge card, such as saying hello to a stranger or ordering something new. Each writes a prediction, tries it in or after session, then scores the match. Keep the cards mild and chosen by the client. In the debrief, look for what surprised them and what that suggests about next steps.', '[{"id": "f0", "type": "textarea", "label": "Rules: take turns, write a guess first, then try the challenge"}, {"id": "f1", "type": "textarea", "label": "The challenge I drew"}, {"id": "f2", "type": "textarea", "label": "My prediction, and how sure I am, 0 to 100"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "How close my guess was, and my score"}, {"id": "f5", "type": "textarea", "label": "Anything that surprised me"}, {"id": "f6", "type": "textarea", "label": "One thing I learned from the debrief"}, {"id": "f7", "type": "textarea", "label": "The challenge I will try next"}]'::jsonb, array['anxiety', 'behavioral experiment', 'play']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('before-during-after-event-plan', 'Before During After Event Plan', 'worksheet'::resource_kind, 'Lays out a plan for an upcoming anxious event in three stages: the lead-up, the moment and the aftermath.', 'Help a client prepare for a worrying event and avoid replaying it afterward.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick one real event in the next week or two. Many clients plan only the event and are caught out by the lead-up and the replay afterward, so give those two stages equal attention. Revisit the sheet at the next session and look at what the plan got right and what to adjust.', '[{"id": "f0", "type": "textarea", "label": "The event I am preparing for and when it is"}, {"id": "f1", "type": "textarea", "label": "What I tend to worry about in the days before"}, {"id": "f2", "type": "textarea", "label": "What I will do in the lead-up to stay steady"}, {"id": "f3", "type": "textarea", "label": "What I will do during the event if anxiety rises"}, {"id": "f4", "type": "textarea", "label": "What I want to do instead of replaying it afterward"}, {"id": "f5", "type": "textarea", "label": "A kind thing I will do for myself once it is over"}, {"id": "f6", "type": "textarea", "label": "Who I could tell about my plan"}]'::jsonb, array['anxiety', 'coping skills', 'scheduling']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('probability-pie-chart', 'Probability Pie Chart', 'cbt'::resource_kind, 'Splits a feared outcome into a pie of all the other things that could happen, then adds how the client could cope.', 'Loosen the pull of a single feared outcome by looking at the full range of possibilities.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to write the feared outcome, then brainstorm every other outcome before assigning slices; work the biggest slices first so the feared one is not sized by feeling alone. Close with coping: even if it happens, what would they do? Expect some clients to resist, and keep the numbers approximate.', '[{"id": "f0", "type": "textarea", "label": "The outcome I am afraid of"}, {"id": "f1", "type": "textarea", "label": "My gut sense of how likely it is, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "Other things that could happen, even unlikely ones"}, {"id": "f3", "type": "textarea", "label": "How big each slice should be, once I list them all"}, {"id": "f4", "type": "textarea", "label": "Evidence for and against my first guess"}, {"id": "f5", "type": "textarea", "label": "If the feared outcome did happen, how I would cope"}, {"id": "f6", "type": "textarea", "label": "How likely it seems now, 0 to 100"}]'::jsonb, array['anxiety', 'thinking traps', 'core CBT']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('anxiety-choice-point', 'Anxiety Choice Point', 'act'::resource_kind, 'Maps a hooked moment: what showed up, what moves away from values and what moves toward them.', 'Help a client notice an anxious moment as a choice about where to put their energy.', array['Adults', 'Teens']::text[], '25 minutes', 'Choice Point is a familiar ACT tool; draw the fork with the client and fill it in from a recent moment. Be even-handed about away moves, because they often work in the short term, and ask what they cost over time. Keep the focus on the next small toward move, not on getting rid of the feeling.', '[{"id": "f0", "type": "textarea", "label": "A recent moment when anxiety showed up"}, {"id": "f1", "type": "textarea", "label": "Thoughts, feelings and sensations that showed up"}, {"id": "f2", "type": "textarea", "label": "What I did that moved me away from what matters"}, {"id": "f3", "type": "textarea", "label": "What that gave me in the short term, and what it cost"}, {"id": "f4", "type": "textarea", "label": "What matters to me in this situation"}, {"id": "f5", "type": "textarea", "label": "What I could do that moves me toward it"}, {"id": "f6", "type": "textarea", "label": "What I could say to myself to make room for the anxiety"}]'::jsonb, array['anxiety', 'values', 'core ACT']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('check-the-facts-for-low-mood', 'Check the Facts for Low Mood', 'dbt'::resource_kind, 'Walks a client through the DBT Check the Facts steps when a low mood is shaping how an event looks.', 'Help a client notice whether an emotion fits the facts of a situation and act accordingly.', array['Adults', 'Teens']::text[], '20 minutes', 'Use a recent event where the client''s mood felt larger than the facts. Work through the steps in order: name the emotion, describe what happened as a camera would, list interpretations, and ask whether the emotion and its intensity fit. Some feelings fit the facts, and that is useful to learn too.', '[{"id": "f0", "type": "textarea", "label": "The emotion I noticed and how strong it was, 0 to 100"}, {"id": "f1", "type": "textarea", "label": "What happened, described only with facts"}, {"id": "f2", "type": "textarea", "label": "The story or interpretation I added"}, {"id": "f3", "type": "textarea", "label": "Other ways to see the situation"}, {"id": "f4", "type": "textarea", "label": "Does the emotion fit the facts? Does its strength fit?"}, {"id": "f5", "type": "textarea", "label": "What I want to do next, and whether it fits my goals"}, {"id": "f6", "type": "textarea", "label": "If it fits, what a skillful response could be"}]'::jsonb, array['depression', 'emotion regulation', 'skills']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('low-energy-connection-plan', 'Low-Energy Connection Plan', 'couples'::resource_kind, 'Helps partners agree on small, doable ways to stay connected when one partner''s energy is low.', 'Keep a couple connected through low-mood weeks without pressure on either partner.', array['Couples']::text[], 'Full session', 'Each partner has their own section so that neither feels blamed. The partner with low energy names what they can offer and what feels like too much; the other partner names what they can offer and how they will look after themselves. Keep the plan small and revisit it weekly, because energy changes.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I can do on a low-energy day"}, {"id": "f1", "type": "textarea", "label": "Partner A: what feels like too much right now"}, {"id": "f2", "type": "textarea", "label": "Partner A: how I will let my partner know how I am"}, {"id": "f3", "type": "textarea", "label": "Partner B: how I can show care without taking over"}, {"id": "f4", "type": "textarea", "label": "Partner B: how I will take care of myself"}, {"id": "f5", "type": "textarea", "label": "Partner B: what I need to hear from my partner"}, {"id": "f6", "type": "textarea", "label": "Together: a small daily moment of connection"}, {"id": "f7", "type": "textarea", "label": "Together: when we will check how the plan is going"}]'::jsonb, array['depression', 'couples', 'connection', 'support']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('mood-color-garden-drawing', 'Mood Color Garden Drawing', 'kids'::resource_kind, 'A child draws a garden where each flower color is a feeling, then adds sunshine and watering for the gloomy patches.', 'Give a child a way to show low or flat feelings and plan small things that help them grow.', array['Children']::text[], '25 minutes', 'Let the child choose colors for sad, tired, mad and happy and fill the garden however they like. Then talk about what each flower needs. Invite the parent in at the end to hear which watering ideas the child picked and to choose one thing the parent will do this week. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw a garden and pick a color for each feeling"}, {"id": "f1", "type": "textarea", "label": "Which flowers are growing the most lately"}, {"id": "f2", "type": "textarea", "label": "Draw what the gloomy flowers need"}, {"id": "f3", "type": "textarea", "label": "One thing that is like sunshine for me"}, {"id": "f4", "type": "textarea", "label": "One thing that is like watering for me"}, {"id": "f5", "type": "textarea", "label": "What a grown-up can do to help my garden this week"}]'::jsonb, array['depression', 'children', 'art', 'play']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('energy-budget-game', 'Energy Budget Game', 'game'::resource_kind, 'Players spend a limited pile of energy tokens on daily tasks and trade off what to do, delay or drop.', 'Help a client plan low-energy days by choosing what matters most with limited energy.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Each player starts with the same number of tokens and draws task cards, such as showering, answering a message or a walk. Players take turns spending tokens, and special cards shift the budget up or down. In the debrief, ask what they would drop first, what they would protect and what rest is worth.', '[{"id": "f0", "type": "textarea", "label": "Rules: each turn, spend tokens on one task or rest"}, {"id": "f1", "type": "textarea", "label": "How many tokens I started with"}, {"id": "f2", "type": "textarea", "label": "The tasks I chose and why"}, {"id": "f3", "type": "textarea", "label": "What I delayed or dropped"}, {"id": "f4", "type": "textarea", "label": "What I protected even when tokens were low"}, {"id": "f5", "type": "textarea", "label": "How this looks like my real days"}, {"id": "f6", "type": "textarea", "label": "One real task I could drop or shrink this week"}, {"id": "f7", "type": "textarea", "label": "One real thing that gives me energy back"}]'::jsonb, array['depression', 'behavioral activation', 'play']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('daily-basics-anchor-sheet', 'Daily Basics Anchor Sheet', 'worksheet'::resource_kind, 'Tracks a few daily anchors, such as sleep, light, movement, a meal and one contact, to build a steady floor.', 'Give a client a short, doable list of daily basics that support mood on hard days.', array['Adults', 'Teens']::text[], 'One week', 'Choose three or four anchors with the client and keep each one small, like opening the curtains or sending one message. The point is a floor, not a performance, so score completion simply and discuss what got in the way without judgment. Coordinate with their physician on any health-related anchor.', '[{"id": "f0", "type": "textarea", "label": "The anchors I chose for this week"}, {"id": "f1", "type": "textarea", "label": "What time I woke and went to bed"}, {"id": "f2", "type": "textarea", "label": "How much daylight or outside time I got"}, {"id": "f3", "type": "textarea", "label": "Movement I did, even a little"}, {"id": "f4", "type": "textarea", "label": "A meal or drink I had"}, {"id": "f5", "type": "textarea", "label": "One person I had contact with"}, {"id": "f6", "type": "textarea", "label": "What got in the way on hard days"}, {"id": "f7", "type": "textarea", "label": "Which anchor I want to keep next week"}]'::jsonb, array['depression', 'routines', 'self-monitoring']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('deadline-panic-thought-record', 'Deadline Panic Thought Record', 'cbt'::resource_kind, 'A thought record for the last-minute surge of dread before something is due.', 'Separate the thoughts that fuel last-minute panic from the steps that are still possible.', array['Adults', 'Teens']::text[], '25 minutes', 'Use it with a recent deadline your client met in a rush or missed. Many clients list only the feelings, so ask for the exact sentence in their head at the moment they froze. The balanced-thought box works best when it names one small step that is still available, not a pep talk. Your judgment decides how far to push the evidence column.', '[{"id": "f0", "type": "textarea", "label": "The deadline and when you first noticed it"}, {"id": "f1", "type": "textarea", "label": "What I felt in my body when it got close"}, {"id": "f2", "type": "textarea", "label": "The thought that hit hardest, in my own words"}, {"id": "f3", "type": "textarea", "label": "Evidence the thought is true"}, {"id": "f4", "type": "textarea", "label": "Evidence that is missing or leaves it out"}, {"id": "f5", "type": "textarea", "label": "A more balanced thought"}, {"id": "f6", "type": "textarea", "label": "One small step still open to me right now"}, {"id": "f7", "type": "textarea", "label": "How strong the dread feels now, 0 to 10"}]'::jsonb, array['ADHD', 'core CBT', 'thinking traps']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('distraction-defusion-cards', 'Distraction Defusion Cards', 'act'::resource_kind, 'Cards for noticing a pull toward something else and labeling it without obeying it.', 'Practice noticing the pull of a distraction and returning to a chosen task.', array['Adults', 'Teens']::text[], '20 minutes, then daily for a week', 'Clients often try to force the pull away, which tends to make it louder. Have them write the pulls as phrases, such as I should check my phone, and practice prefacing them with I am having the thought that. Keep the aim on returning to the task, not on silencing the thoughts. Review the cards together at the next session.', '[{"id": "f0", "type": "textarea", "label": "Three pulls that show up when I try to focus"}, {"id": "f1", "type": "textarea", "label": "Write each one starting with I am having the thought that"}, {"id": "f2", "type": "textarea", "label": "What I was working on when the pull came"}, {"id": "f3", "type": "textarea", "label": "Where I felt the pull in my body"}, {"id": "f4", "type": "textarea", "label": "What I did next, and what I would choose to do instead"}, {"id": "f5", "type": "textarea", "label": "One value this task connects to"}, {"id": "f6", "type": "textarea", "label": "A sentence I can say when a pull arrives"}]'::jsonb, array['ADHD', 'core ACT', 'defusion']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('stop-skill-impulse-card', 'STOP Skill Impulse Card', 'dbt'::resource_kind, 'A pocket card that walks a client through Stop, Take a step back, Observe, Proceed mindfully.', 'Build a short pause between an impulse and the action that follows it.', array['Adults', 'Teens']::text[], '15 minutes', 'Rehearse with a low-stakes impulse first, such as interrupting or an unplanned purchase, before the client tries it when emotions run high. Clients often skip the observe step, so have them name one thing they notice in the body and one in the room. The card is a prompt for practice between sessions, and you decide how to pace it.', '[{"id": "f0", "type": "textarea", "label": "An impulse I often act on too fast"}, {"id": "f1", "type": "textarea", "label": "What stopping would look like for me"}, {"id": "f2", "type": "textarea", "label": "What I notice in my body when I step back"}, {"id": "f3", "type": "textarea", "label": "What I notice in my thoughts and the room"}, {"id": "f4", "type": "textarea", "label": "What I want in this situation"}, {"id": "f5", "type": "textarea", "label": "My mindful next move"}, {"id": "f6", "type": "textarea", "label": "Where I will keep this card"}]'::jsonb, array['ADHD', 'distress tolerance', 'skills']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('weekly-household-meeting-agenda', 'Weekly Household Meeting Agenda', 'couples'::resource_kind, 'A shared agenda for a short weekly meeting about chores, calendars and appreciation.', 'Give both partners a predictable time to coordinate the week without nagging.', array['Couples']::text[], '30 minutes weekly', 'Each partner fills in their own boxes before the meeting, then you walk through them in session first. The partner who tends to hold the calendar practices handing over one item, and the other partner practices owning it, with a reminder they set themselves. Keep it short and end on appreciation. Adjust the order to fit how the pair actually talks.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what is on my calendar this week"}, {"id": "f1", "type": "textarea", "label": "Partner B: what is on my calendar this week"}, {"id": "f2", "type": "textarea", "label": "Partner A: one task I will own and how I will remember it"}, {"id": "f3", "type": "textarea", "label": "Partner B: one task I will own and how I will remember it"}, {"id": "f4", "type": "textarea", "label": "Something I appreciated about my partner last week"}, {"id": "f5", "type": "textarea", "label": "Something that did not work, said without blame"}, {"id": "f6", "type": "textarea", "label": "What we will try differently this week"}]'::jsonb, array['ADHD', 'couples', 'routines']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('morning-routine-picture-track', 'Morning Routine Picture Track', 'kids'::resource_kind, 'A child draws each morning step on a strip and builds a track the parent helps them follow.', 'Help a child see their morning steps in order and take ownership of them.', array['Children']::text[], '30 minutes', 'Have the child draw four to six morning steps on cards and lay them along a paper track with a start and a finish flag. The parent''s role is to point to the card, not to repeat instructions, and to cheer at the finish. Send the track home and ask the parent to report back on which step needs a redesign. If a child discloses harm while you draw together, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Steps I drew on my track, in order"}, {"id": "f1", "type": "textarea", "label": "The step that is hardest for me"}, {"id": "f2", "type": "textarea", "label": "What my parent does to help, like pointing to a card"}, {"id": "f3", "type": "textarea", "label": "What I do when I get stuck on a step"}, {"id": "f4", "type": "textarea", "label": "How I celebrate at the finish flag"}, {"id": "f5", "type": "textarea", "label": "What my parent noticed and wants to change"}]'::jsonb, array['ADHD', 'children', 'routines', 'parenting']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('refusal-skills-role-play-cards', 'Refusal Skills Role-Play Cards', 'game'::resource_kind, 'A turn-taking card game for practicing how to decline substance use offers.', 'Rehearse short, firm ways of declining when substance use is offered.', array['Adults', 'Groups']::text[], '30 minutes', 'Players draw a situation card, such as a coworker offering a drink or an old friend stopping by, and the other player reads the offer while the first responds. Rotate roles every turn. Keep the responses short and practice saying them out loud. Debrief on which replies felt natural and which felt scripted, and let the client choose two to keep.', '[{"id": "f0", "type": "textarea", "label": "Situations I most want to practice"}, {"id": "f1", "type": "textarea", "label": "My shortest way of saying no"}, {"id": "f2", "type": "textarea", "label": "A reply that gives a reason, and one that gives none"}, {"id": "f3", "type": "textarea", "label": "A person I would text for help after an offer"}, {"id": "f4", "type": "textarea", "label": "What I noticed in my body while declining"}, {"id": "f5", "type": "textarea", "label": "The two replies I will keep, and when I will use them"}]'::jsonb, array['addiction', 'play', 'urges']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('weekly-rhythm-rebuild-planner', 'Weekly Rhythm Rebuild Planner', 'worksheet'::resource_kind, 'A seven-day planner for filling the times that used to involve substance use.', 'Plan meaningful activities for the hours that used to be built around substance use.', array['Adults']::text[], '30 minutes, then one week', 'Ask the client to mark the hours when substance use used to happen and plan something concrete in each one, with a person attached where possible. Many clients plan too much at once, so help them choose a few anchors and leave space. Check in on what actually happened the following session and treat gaps as information, not failure.', '[{"id": "f0", "type": "textarea", "label": "Times of day and days of the week that used to involve substance use"}, {"id": "f1", "type": "textarea", "label": "What I will do in each of those times"}, {"id": "f2", "type": "textarea", "label": "Who I will do it with or tell about it"}, {"id": "f3", "type": "textarea", "label": "What I need to have ready ahead of time"}, {"id": "f4", "type": "textarea", "label": "One thing I enjoy that I have not made time for"}, {"id": "f5", "type": "textarea", "label": "What got in the way last week"}, {"id": "f6", "type": "textarea", "label": "One change I will make to next week''s plan"}]'::jsonb, array['addiction', 'routines', 'relapse prevention']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('permission-thoughts-record', 'Permission Thoughts Record', 'cbt'::resource_kind, 'A record for catching I deserve this and one will not hurt thoughts before substance use.', 'Spot permission-giving thoughts and weigh them against what the client values.', array['Adults']::text[], '25 minutes', 'Permission-giving thoughts often sound reasonable in the moment, so ask for the exact words and the situation around them. Work through one recent example in session before assigning it. The alternative thought should be one the client believes, not a slogan. You decide whether to keep going into the beliefs underneath.', '[{"id": "f0", "type": "textarea", "label": "The situation and what I was feeling"}, {"id": "f1", "type": "textarea", "label": "The permission thought, word for word"}, {"id": "f2", "type": "textarea", "label": "How believable it felt, 0 to 100"}, {"id": "f3", "type": "textarea", "label": "What it let me do or told me I could skip"}, {"id": "f4", "type": "textarea", "label": "What happened afterward"}, {"id": "f5", "type": "textarea", "label": "A response I could say to that thought"}, {"id": "f6", "type": "textarea", "label": "What I would want to have done instead"}]'::jsonb, array['addiction', 'core CBT', 'thinking traps', 'urges']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('urge-passengers-on-the-bus', 'Urge Passengers on the Bus', 'act'::resource_kind, 'An ACT bus metaphor worksheet for carrying urges along without letting them drive.', 'Practice carrying urges as passengers while the client keeps driving toward their values.', array['Adults']::text[], '25 minutes', 'Walk through the bus metaphor aloud, then let the client draw their own bus with the urges as passengers. Clients often want to throw the passengers off the bus, so notice that effort and ask what it costs them. Keep returning to the direction they chose. Read the last prompt aloud together.', '[{"id": "f0", "type": "textarea", "label": "Where I want my bus to go, in a few words"}, {"id": "f1", "type": "textarea", "label": "The urges that ride along, and what they say"}, {"id": "f2", "type": "textarea", "label": "What I have done to try to get them off the bus"}, {"id": "f3", "type": "textarea", "label": "What that cost me or what happened"}, {"id": "f4", "type": "textarea", "label": "What I could do if they stay on while I keep driving"}, {"id": "f5", "type": "textarea", "label": "One small step in my chosen direction this week"}]'::jsonb, array['addiction', 'core ACT', 'values', 'urges']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-decision-card', 'Pros and Cons Decision Card', 'dbt'::resource_kind, 'A DBT pros and cons grid comparing acting on an urge with tolerating it.', 'Compare short-term and long-term outcomes of acting on an urge versus tolerating it.', array['Adults', 'Teens']::text[], '20 minutes', 'Fill in all four quadrants, and be sure the client includes the real pros of using, which builds trust and keeps the exercise honest. Complete it when the client is calm, then carry the card for use when an urge arrives. Look at what the long-term cons of tolerating are, and ask whether any are workable.', '[{"id": "f0", "type": "textarea", "label": "Pros of acting on the urge, now and later"}, {"id": "f1", "type": "textarea", "label": "Cons of acting on the urge, now and later"}, {"id": "f2", "type": "textarea", "label": "Pros of tolerating the urge, now and later"}, {"id": "f3", "type": "textarea", "label": "Cons of tolerating the urge, now and later"}, {"id": "f4", "type": "textarea", "label": "What stands out when I look at all four"}, {"id": "f5", "type": "textarea", "label": "One thing I will do to ride out an urge this week"}]'::jsonb, array['addiction', 'distress tolerance', 'urges', 'decisions']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('soft-start-up-rewrite-sheet', 'Soft Start-Up Rewrite Sheet', 'couples'::resource_kind, 'Both partners rewrite a harsh opener into a gentle request in the Gottman style.', 'Practice raising a complaint without blame so the talk starts calmer.', array['Couples']::text[], '30 minutes', 'Each partner picks a recent harsh opener, writes it down, and then rewrites it using I feel, about what, and I need. Partner A rewrites first while Partner B listens for blame, then swap. Coach the listener to say what they heard before they respond. Stop if the exchange heats up and use whatever pause plan you have agreed on.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a recent harsh opener I used"}, {"id": "f1", "type": "textarea", "label": "Partner A: my rewrite using I feel, about what, and I need"}, {"id": "f2", "type": "textarea", "label": "Partner B: a recent harsh opener I used"}, {"id": "f3", "type": "textarea", "label": "Partner B: my rewrite using I feel, about what, and I need"}, {"id": "f4", "type": "textarea", "label": "What it was like to hear my partner''s softer version"}, {"id": "f5", "type": "textarea", "label": "One request I will start softly this week"}]'::jsonb, array['anger management', 'couples', 'Gottman', 'communication']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('calm-down-jar-craft', 'Calm-Down Jar Craft', 'kids'::resource_kind, 'A child fills a jar with water and glitter and watches it settle while breathing.', 'Give a child a hands-on picture of big feelings settling when they pause and breathe.', array['Children']::text[], '30 minutes', 'Make the jar together and let the child shake it as the big feeling, then breathe until the glitter settles. The parent''s role is to keep a jar at home, offer it without commands, and stay close while the child uses it, never as a punishment. Ask the child to draw what the jar looks like when they are calm. If a child discloses harm while you draw together, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "What my big feeling looks like when I shake the jar"}, {"id": "f1", "type": "textarea", "label": "A drawing of my jar when it is calm"}, {"id": "f2", "type": "textarea", "label": "What I did while I watched the glitter settle"}, {"id": "f3", "type": "textarea", "label": "When I could use my jar at home"}, {"id": "f4", "type": "textarea", "label": "What my parent does when I use my jar"}, {"id": "f5", "type": "textarea", "label": "What I notice in my body when it settles"}]'::jsonb, array['anger management', 'children', 'play', 'regulation']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('trigger-tag-team-cards', 'Trigger Tag Team Cards', 'game'::resource_kind, 'A group card game where players trade trigger situations and brainstorm calmer moves.', 'Practice naming triggers and generating a calmer choice for each in a safe, playful setting.', array['Teens', 'Groups']::text[], '40 minutes', 'Each player writes a trigger on a card, such as being interrupted or ignored, and the deck is shuffled. On a turn, a player draws a card and names a first body sign, then tags a teammate for a calmer move. Keep it light and watch that no one is put on the spot. Debrief on which moves players would actually try.', '[{"id": "f0", "type": "textarea", "label": "A trigger I put in the deck"}, {"id": "f1", "type": "textarea", "label": "The first body sign I notice with it"}, {"id": "f2", "type": "textarea", "label": "A calmer move a teammate suggested"}, {"id": "f3", "type": "textarea", "label": "A move I would try this week"}, {"id": "f4", "type": "textarea", "label": "How it felt to hear that others share triggers"}, {"id": "f5", "type": "textarea", "label": "One thing I will do differently"}]'::jsonb, array['anger management', 'group', 'triggers', 'play']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('anger-cost-and-payoff-ledger', 'Anger Cost and Payoff Ledger', 'worksheet'::resource_kind, 'A two-column ledger of what anger gets a client and what it costs them.', 'Help a client weigh honestly what anger gives them against what it takes away.', array['Adults']::text[], '25 minutes', 'Start with the payoffs, since anger tends to work in the short run and clients stop trusting a list that skips this. Then fill the cost column across relationships, health and work. Avoid arguing with any entry. Ask the client what they see when they read both columns and what need the payoff points to.', '[{"id": "f0", "type": "textarea", "label": "What anger gets me in the moment"}, {"id": "f1", "type": "textarea", "label": "What need sits under each payoff"}, {"id": "f2", "type": "textarea", "label": "What anger has cost me with people"}, {"id": "f3", "type": "textarea", "label": "What it has cost me in my body and health"}, {"id": "f4", "type": "textarea", "label": "What it has cost me at work or in daily life"}, {"id": "f5", "type": "textarea", "label": "What I see when I read both columns"}, {"id": "f6", "type": "textarea", "label": "One cost I would most like to change"}]'::jsonb, array['anger management', 'values', 'self-monitoring']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('other-reasons-spoke-sheet', 'Other Reasons Spoke Sheet', 'cbt'::resource_kind, 'A spoke diagram for generating other explanations for a behavior that sparked anger.', 'Loosen the first hostile explanation by generating other possible reasons for what happened.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick one recent event where the client assumed the other person meant harm. Have the client write the first explanation in the center and fill the outer spokes with at least four others, including ones they find unlikely. The aim is flexibility, not deciding the person meant well. Ask what they would need to know to tell which fits.', '[{"id": "f0", "type": "textarea", "label": "What happened and what the person did"}, {"id": "f1", "type": "textarea", "label": "My first explanation of why they did it"}, {"id": "f2", "type": "textarea", "label": "How angry I felt, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "Four other explanations, even unlikely ones"}, {"id": "f4", "type": "textarea", "label": "What I would need to know to tell which one fits"}, {"id": "f5", "type": "textarea", "label": "How angry I feel now, 0 to 10"}, {"id": "f6", "type": "textarea", "label": "What I could do or say next"}]'::jsonb, array['anger management', 'core CBT', 'thinking traps']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('compulsion-choice-point-sheet', 'Compulsion Choice Point Sheet', 'act'::resource_kind, 'A choice point map of the pull toward a ritual, the away move, and the toward move.', 'Help the client notice the moment of choice between a ritual and a values-based action.', array['Adults', 'Teens']::text[], '30 minutes', 'Work from a recent example where the urge to do a ritual showed up. Clients often find the hooks (what the thought says, how the body feels) easy to name and the toward move harder, so spend time on what they would be doing if the urge were not in charge. Keep it a map of choices, not a test of willpower.', '[{"id": "f0", "type": "textarea", "label": "The situation where the urge showed up."}, {"id": "f1", "type": "textarea", "label": "The thoughts and feelings that hooked me."}, {"id": "f2", "type": "textarea", "label": "What I did to get relief (my away move)."}, {"id": "f3", "type": "textarea", "label": "What that move cost me over the next hour."}, {"id": "f4", "type": "textarea", "label": "Someone or something that matters to me in this moment."}, {"id": "f5", "type": "textarea", "label": "One toward move I could try next time, even a small one."}, {"id": "f6", "type": "textarea", "label": "What I will say to the urge while I do it."}]'::jsonb, array['OCD', 'core ACT', 'choice point', 'values']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('intrusive-thought-radical-acceptance-card', 'Radical Acceptance of Intrusive Thoughts Card', 'dbt'::resource_kind, 'A pocket card that walks through radical acceptance when an unwanted thought arrives.', 'Practice letting an unwanted thought be there without fighting it or performing a ritual.', array['Adults', 'Teens']::text[], '20 minutes, then daily practice', 'Introduce radical acceptance as agreeing that the thought is present right now, not agreeing that it is true or wanted. Rehearse it once in session with a mild thought before the client uses it alone. Watch for acceptance turning into a covert ritual, such as repeating the phrase until the anxiety drops, and name that gently.', '[{"id": "f0", "type": "textarea", "label": "An unwanted thought that shows up for me."}, {"id": "f1", "type": "textarea", "label": "What I usually do to push it away."}, {"id": "f2", "type": "textarea", "label": "How it feels to fight it."}, {"id": "f3", "type": "textarea", "label": "What it would mean to let it be here, like weather passing."}, {"id": "f4", "type": "textarea", "label": "The accepting statement I will say (for example, this thought is here right now)."}, {"id": "f5", "type": "textarea", "label": "What I will do next, with the thought still present."}, {"id": "f6", "type": "textarea", "label": "How it went when I tried it."}]'::jsonb, array['OCD', 'radical acceptance', 'distress tolerance']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('kind-no-reassurance-agreement', 'Kind No Agreement for Reassurance', 'couples'::resource_kind, 'A written plan for how one partner asks for reassurance and the other responds with warmth instead of answers.', 'Give both partners a shared, caring way to handle reassurance requests together.', array['Couples']::text[], 'Full session', 'Have the partner who struggles with doubt write their part first, then the supporting partner writes theirs, so neither one feels managed. Both partners should agree on a warm response that does not answer the question, and on what the asking partner does with the feeling afterward. Expect to revisit the wording after the first week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I will notice I am about to ask for reassurance."}, {"id": "f1", "type": "textarea", "label": "Partner A: what I will do instead of asking, or after I ask."}, {"id": "f2", "type": "textarea", "label": "Partner B: how I will recognize a reassurance request."}, {"id": "f3", "type": "textarea", "label": "Partner B: the kind words I will use that do not answer the question."}, {"id": "f4", "type": "textarea", "label": "Both: what we will do together when it is hard for both of us."}, {"id": "f5", "type": "textarea", "label": "Both: how we will thank each other afterward."}, {"id": "f6", "type": "textarea", "label": "Both: when we will review this plan."}]'::jsonb, array['OCD', 'reassurance', 'couples', 'support']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('brave-choice-comic-strip', 'Brave Choice Comic Strip', 'kids'::resource_kind, 'The child draws a four-panel comic of a bossy worry, the urge, a brave choice and what happens next.', 'Help a child see the choice between obeying the worry and trying a brave move.', array['Children']::text[], '30 minutes', 'Draw the panels with the child, letting them design the worry character and decide how the hero responds. The parent joins for the last panel and learns one cheer-on phrase that does not give reassurance or help with the ritual. If a child discloses something worrying about their safety, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Panel 1: Draw the bossy worry and what it says."}, {"id": "f1", "type": "textarea", "label": "Panel 2: Draw the urge in my body."}, {"id": "f2", "type": "textarea", "label": "Panel 3: Draw the brave choice the hero makes."}, {"id": "f3", "type": "textarea", "label": "Panel 4: Draw what happens when the hero waits."}, {"id": "f4", "type": "textarea", "label": "What my parent will say to cheer me on."}, {"id": "f5", "type": "textarea", "label": "What my parent will not do, so the worry does not win."}]'::jsonb, array['OCD', 'children', 'externalizing', 'parenting']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('maybe-roulette-game', 'Maybe Roulette Game', 'game'::resource_kind, 'Players spin or roll for an uncertain statement and answer it with a calm maybe.', 'Practice sitting with not knowing in a playful group setting.', array['Teens', 'Groups']::text[], '25 minutes', 'Write cards such as maybe the door is unlocked or maybe I said something wrong, and keep the early ones mild. Each player draws, reads the card aloud and replies with a maybe statement and one small thing they would do anyway. Nobody may check, ask for reassurance or fix the card. Use the debrief to compare how hard each card felt.', '[{"id": "f0", "type": "textarea", "label": "Cards we wrote for our deck."}, {"id": "f1", "type": "textarea", "label": "The card that felt easiest."}, {"id": "f2", "type": "textarea", "label": "The card that felt hardest."}, {"id": "f3", "type": "textarea", "label": "What I said back to the maybe."}, {"id": "f4", "type": "textarea", "label": "What I noticed in my body while I waited."}, {"id": "f5", "type": "textarea", "label": "Something I would try with an uncertain thought this week."}]'::jsonb, array['OCD', 'uncertainty', 'group', 'play']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('panic-trigger-place-map', 'Panic Trigger Place Map', 'worksheet'::resource_kind, 'A map of places and situations the client has started to avoid or enter with dread.', 'Show how a pattern of avoidance has grown around panic and where it has shrunk life.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask the client to draw home at the center and mark places by how much dread they carry, from easy to hard. Look together at what has dropped off the map and which places matter most. This is raw material for planning practice, so avoid pushing toward the hardest spot while the map is still being drawn.', '[{"id": "f0", "type": "textarea", "label": "Places I go easily."}, {"id": "f1", "type": "textarea", "label": "Places I enter with dread."}, {"id": "f2", "type": "textarea", "label": "Places I have stopped going to."}, {"id": "f3", "type": "textarea", "label": "What I do to make it through the hard ones."}, {"id": "f4", "type": "textarea", "label": "Who or what I carry with me for safety."}, {"id": "f5", "type": "textarea", "label": "What I miss most on the places I avoid."}, {"id": "f6", "type": "textarea", "label": "The place I would most like to get back."}]'::jsonb, array['panic attacks', 'avoidance', 'monitoring']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('panic-safety-behavior-test', 'Panic Safety Behavior Test', 'cbt'::resource_kind, 'A behavioral experiment that compares a feared situation with and without a safety behavior.', 'Test whether the feared outcome happens when a safety behavior is dropped.', array['Adults', 'Teens']::text[], '30 minutes, then one week', 'Pick one safety behavior, such as carrying water, sitting near the exit or checking a pulse, and plan the experiment in session. Have the client predict the outcome with a rating, run it once with and once without the behavior, and then compare. Go slowly and agree on the size of the step, since a step too big can reinforce the fear.', '[{"id": "f0", "type": "textarea", "label": "The safety behavior I rely on."}, {"id": "f1", "type": "textarea", "label": "What I fear will happen if I drop it."}, {"id": "f2", "type": "textarea", "label": "How much I believe that, from 0 to 100."}, {"id": "f3", "type": "textarea", "label": "How I will run the experiment, and where."}, {"id": "f4", "type": "textarea", "label": "What actually happened."}, {"id": "f5", "type": "textarea", "label": "What I learned about the prediction."}, {"id": "f6", "type": "textarea", "label": "How much I believe it now, from 0 to 100."}]'::jsonb, array['panic attacks', 'core CBT', 'behavioral experiment', 'exposure']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('passengers-on-the-bus-panic', 'Passengers on the Bus: Panic Edition', 'act'::resource_kind, 'A bus metaphor where panic sensations and thoughts ride along while the client keeps driving toward a value.', 'Help the client keep moving toward what matters while panic rides along.', array['Adults', 'Teens']::text[], '30 minutes', 'Draw the bus with the client, with panic sensations and frightening thoughts as loud passengers. The point is not to throw them off but to keep driving. Ask what direction the client wants to take, and expect them to say at first that the passengers have to be quiet. Stay with what they would do if the passengers could stay.', '[{"id": "f0", "type": "textarea", "label": "Where I want my bus to go (a value or a place that matters)."}, {"id": "f1", "type": "textarea", "label": "The loud passengers: sensations I notice."}, {"id": "f2", "type": "textarea", "label": "The loud passengers: thoughts they shout."}, {"id": "f3", "type": "textarea", "label": "What they tell me to do."}, {"id": "f4", "type": "textarea", "label": "What happens when I do what they say."}, {"id": "f5", "type": "textarea", "label": "What I could do while they ride along."}, {"id": "f6", "type": "textarea", "label": "One small drive I will take this week."}]'::jsonb, array['panic attacks', 'core ACT', 'values', 'willingness']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('tipp-cool-down-plan', 'TIPP Cool-Down Plan for Panic', 'dbt'::resource_kind, 'A plan built around temperature, intense exercise, paced breathing and paired muscle relaxation.', 'Let the client choose and rehearse TIPP skills ahead of a surge of panic.', array['Adults', 'Teens']::text[], '30 minutes', 'Walk through each TIPP skill and let the client choose which two to rehearse in session. Check for any health concerns, such as a heart condition, before cold water or intense exercise, and confirm with the client''s own provider where that applies. Clients often find paced breathing with a longer out-breath helps most; encourage practice while calm.', '[{"id": "f0", "type": "textarea", "label": "The signs that panic is rising for me."}, {"id": "f1", "type": "textarea", "label": "T: How I will use cold, like a cold pack or cold water."}, {"id": "f2", "type": "textarea", "label": "I: A short burst of exercise I can do where I am."}, {"id": "f3", "type": "textarea", "label": "P: How I will breathe, with a longer out-breath."}, {"id": "f4", "type": "textarea", "label": "P: How I will tense and release my muscles."}, {"id": "f5", "type": "textarea", "label": "The two skills I will rehearse this week."}, {"id": "f6", "type": "textarea", "label": "How I felt after practicing them."}]'::jsonb, array['panic attacks', 'distress tolerance', 'TIPP', 'regulation']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('after-the-panic-debrief-conversation', 'After the Panic Debrief Conversation', 'couples'::resource_kind, 'A short guide for both partners to talk through a panic episode once it has passed.', 'Help both partners reflect on what helped and what to change next time.', array['Couples']::text[], '30 minutes', 'Teach this as a calm conversation held hours after panic, never during it. The partner who had the panic leads with what helped, and the other partner shares what they noticed and felt. Watch for the supporting partner slipping into fixing or lecturing, and for the other partner feeling like a burden. Keep it brief and kind.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I experienced, in my own words."}, {"id": "f1", "type": "textarea", "label": "Partner A: what my partner did that helped."}, {"id": "f2", "type": "textarea", "label": "Partner B: what I noticed and how I felt."}, {"id": "f3", "type": "textarea", "label": "Partner B: what I wasn''t sure how to do."}, {"id": "f4", "type": "textarea", "label": "Both: one thing to keep doing."}, {"id": "f5", "type": "textarea", "label": "Both: one thing to change next time."}, {"id": "f6", "type": "textarea", "label": "Both: how we will care for ourselves after."}]'::jsonb, array['panic attacks', 'couples', 'support', 'communication']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('calm-down-corner-builder', 'Calm-Down Corner Builder', 'kids'::resource_kind, 'The child designs and builds a cozy corner at home with things that help big feelings settle.', 'Give a child a familiar place and tools for settling, set up together with a parent.', array['Children']::text[], '40 minutes', 'Build a mock corner on paper or from pillows, letting the child pick the items, colors and a name for the space. The parent''s role is to offer the corner as a calm place, never as a punishment, and to sit nearby when asked. If a child discloses something about their safety while drawing, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw or list what goes in my corner."}, {"id": "f1", "type": "textarea", "label": "What I will call my corner."}, {"id": "f2", "type": "textarea", "label": "Something soft to hold or sit on."}, {"id": "f3", "type": "textarea", "label": "Something to look at or listen to."}, {"id": "f4", "type": "textarea", "label": "How my parent will help when I go there."}, {"id": "f5", "type": "textarea", "label": "How I will know I am ready to come back out."}]'::jsonb, array['parenting', 'children', 'regulation', 'routines']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('rewind-and-redo-family-game', 'Rewind and Redo Family Game', 'game'::resource_kind, 'Family members act out a tough moment, then rewind and play it again with a calmer response.', 'Give a family a playful way to practice a different response to a hard moment.', array['Children', 'Groups']::text[], '30 minutes', 'Set the rules first: each person chooses a real but mild scene, one parent and one child swap roles, and anyone can call rewind with a hand signal. Play the scene as it went, then redo it with one new move. Keep it silly enough to laugh and stay in charge of the pace. Close with a debrief and cheer the effort, not the performance.', '[{"id": "f0", "type": "textarea", "label": "A scene we picked to act out."}, {"id": "f1", "type": "textarea", "label": "What happened the first time."}, {"id": "f2", "type": "textarea", "label": "The rewind move we tried."}, {"id": "f3", "type": "textarea", "label": "What changed in the second round."}, {"id": "f4", "type": "textarea", "label": "What it was like to play each other''s part."}, {"id": "f5", "type": "textarea", "label": "One redo we will try at home this week."}]'::jsonb, array['parenting', 'play', 'family', 'communication']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('weekly-family-meeting-agenda', 'Weekly Family Meeting Agenda', 'worksheet'::resource_kind, 'A fifteen-minute agenda for a weekly family check-in with thanks, planning and one problem to solve.', 'Create a predictable weekly time for a family to appreciate, plan and solve together.', array['Adults', 'Groups']::text[], '15 minutes weekly', 'Help the parent set a fixed time and keep the meeting short and mostly positive. Each person gets a turn to share thanks, and only one problem is picked per meeting. Parents often try to use it for lectures; coach them to listen first, let children suggest solutions and let the family choose together.', '[{"id": "f0", "type": "textarea", "label": "Day and time of our meeting."}, {"id": "f1", "type": "textarea", "label": "Who will run it this week."}, {"id": "f2", "type": "textarea", "label": "One thing each person appreciates about someone else."}, {"id": "f3", "type": "textarea", "label": "What is coming up this week."}, {"id": "f4", "type": "textarea", "label": "The one problem we will solve today."}, {"id": "f5", "type": "textarea", "label": "Ideas everyone offered."}, {"id": "f6", "type": "textarea", "label": "The idea we chose and how we will check it."}]'::jsonb, array['parenting', 'family', 'communication', 'routines']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('child-behavior-meaning-check', 'Child Behavior Meaning Check', 'cbt'::resource_kind, 'A parent thought record for the story they tell about a child''s behavior in a hard moment.', 'Help a parent notice and test the meaning they give to a child''s behavior.', array['Adults']::text[], '30 minutes', 'Choose a recent moment when the parent''s reaction felt bigger than the event. Look for mind-reading and permanent labels, such as he is doing this on purpose or she never listens, and have the parent consider other explanations, including what the child might need. Keep the tone curious; parents often carry shame about their reactions.', '[{"id": "f0", "type": "textarea", "label": "What my child did, as a camera would record it."}, {"id": "f1", "type": "textarea", "label": "The story I told myself about why."}, {"id": "f2", "type": "textarea", "label": "How I felt and what I did."}, {"id": "f3", "type": "textarea", "label": "How much I believed the story, from 0 to 100."}, {"id": "f4", "type": "textarea", "label": "Other explanations that might also be true."}, {"id": "f5", "type": "textarea", "label": "What my child may have needed in that moment."}, {"id": "f6", "type": "textarea", "label": "A response that fits what I now think."}]'::jsonb, array['parenting', 'core CBT', 'thinking traps', 'regulation']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('hooked-parent-moments-sheet', 'Hooked and Unhooked Parent Moments', 'act'::resource_kind, 'A sheet for spotting the hooks that pull a parent off course and what unhooking looks like.', 'Help a parent notice when thoughts and feelings pull them away from the parent they want to be.', array['Adults']::text[], '30 minutes', 'Ask for one recent hooked moment and one unhooked one so the client sees that the skill already exists. Name the hooks together, such as the thought that others will think I am failing, and let the client pick a way to unhook in the moment. Expect self-judgment, and invite compassion for how hard the moments are.', '[{"id": "f0", "type": "textarea", "label": "A moment when I got hooked with my child."}, {"id": "f1", "type": "textarea", "label": "The thoughts that hooked me."}, {"id": "f2", "type": "textarea", "label": "The feelings that hooked me."}, {"id": "f3", "type": "textarea", "label": "What I did, and what it cost."}, {"id": "f4", "type": "textarea", "label": "The kind of parent I want to be in that moment."}, {"id": "f5", "type": "textarea", "label": "How I could unhook, for example by naming the hook or pausing."}, {"id": "f6", "type": "textarea", "label": "A moment this week when I did unhook."}]'::jsonb, array['parenting', 'core ACT', 'values', 'defusion']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('sleep-deprived-wise-mind-card', 'Sleep-Deprived Wise Mind Card', 'dbt'::resource_kind, 'A wise mind check-in card for the foggy, emotional hours of newborn care.', 'Help a new parent find a steadier choice when exhaustion is driving.', array['Adults']::text[], '20 minutes', 'Walk your client through the card once in session using a recent rough night. Exhaustion tends to push people toward emotion mind, so keep the steps short enough to use half awake. Help them pick one cue, such as a feed or a diaper change, to prompt the card, and invite them to adapt the wording until it sounds like them.', '[{"id": "f0", "type": "textarea", "label": "A recent moment when exhaustion made everything feel bigger"}, {"id": "f1", "type": "textarea", "label": "What emotion mind was telling me"}, {"id": "f2", "type": "textarea", "label": "What reasonable mind would point out"}, {"id": "f3", "type": "textarea", "label": "What I already know deep down that I need right now"}, {"id": "f4", "type": "textarea", "label": "One small wise action I can take in the next hour"}, {"id": "f5", "type": "textarea", "label": "The cue that will remind me to pause (a feed, a diaper change, a sound)"}, {"id": "f6", "type": "textarea", "label": "Who I can text if the card is not enough"}]'::jsonb, array['perinatal and postpartum', 'regulation', 'skills']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('handover-words-for-new-parents', 'Handover Words for New Parents', 'couples'::resource_kind, 'Partners script the words they use when handing the baby over and asking for a break.', 'Make asking for and giving a break feel cooperative instead of critical.', array['Couples']::text[], '30 minutes', 'Ask both partners to fill in their own side before sharing. The partner at home with the baby often holds back requests for fear of sounding ungrateful, while the other partner may be guessing at what helps. Have each partner say their script aloud and let the other respond, then adjust wording together. Keep the focus on the handover moment, not on who does more overall.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a handover moment that goes badly for me now"}, {"id": "f1", "type": "textarea", "label": "Partner B: a handover moment that goes badly for me now"}, {"id": "f2", "type": "textarea", "label": "Partner A: words I will use to ask for a break"}, {"id": "f3", "type": "textarea", "label": "Partner B: words I will use to ask for a break"}, {"id": "f4", "type": "textarea", "label": "Partner A: how I want to be thanked or acknowledged"}, {"id": "f5", "type": "textarea", "label": "Partner B: how I want to be thanked or acknowledged"}, {"id": "f6", "type": "textarea", "label": "What we will say when either of us has nothing left to give"}, {"id": "f7", "type": "textarea", "label": "The one handover habit we will try this week"}]'::jsonb, array['perinatal and postpartum', 'couples', 'communication']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('big-sibling-new-baby-feelings-house', 'Big Sibling Feelings House', 'kids'::resource_kind, 'A child draws a house with a room for each feeling about the new baby.', 'Give an older child a safe way to show mixed feelings about a new sibling.', array['Children']::text[], '25 minutes', 'Have the child draw a house and fill each room with a feeling about the baby, using any colors they like. Jealousy and pride often sit in rooms side by side, and both are fine. Show the parent how to answer with listening instead of fixing, and set up one short one-on-one time at home. If a child discloses harm or neglect, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw a house with a room for each feeling about the baby, then name the rooms"}, {"id": "f1", "type": "textarea", "label": "Which room is the biggest right now?"}, {"id": "f2", "type": "textarea", "label": "What does the baby do that makes the angry room bigger?"}, {"id": "f3", "type": "textarea", "label": "What does the baby do that makes the happy room bigger?"}, {"id": "f4", "type": "textarea", "label": "Something I would like to do with just my parent"}, {"id": "f5", "type": "textarea", "label": "What my parent will do when I show them a room (parent fills in)"}, {"id": "f6", "type": "textarea", "label": "One thing I can do when a feeling room gets too full"}]'::jsonb, array['perinatal and postpartum', 'children', 'family', 'play']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('night-shift-bingo', 'Night Shift Bingo', 'game'::resource_kind, 'A bingo game where new parents mark off the shared and surprising parts of the first months.', 'Normalize common new-parent experiences and open up honest conversation.', array['Adults', 'Groups']::text[], '30 minutes', 'Make cards of 16 squares with experiences such as crying in a parking lot, loving and resenting the baby in the same hour, and not recognizing yourself. Players take turns calling a square from their own life and marking it; others mark it only if it is true for them. After a line, the caller shares what helped. Debrief on what felt surprising. Allow passes so no one has to disclose more than they choose.', '[{"id": "f0", "type": "textarea", "label": "Squares I would add to our bingo card"}, {"id": "f1", "type": "textarea", "label": "The square I marked that surprised me"}, {"id": "f2", "type": "textarea", "label": "A square nobody else marked"}, {"id": "f3", "type": "textarea", "label": "Something I heard that made me feel less alone"}, {"id": "f4", "type": "textarea", "label": "One thing someone said that I might try"}, {"id": "f5", "type": "textarea", "label": "How I felt when I said a square out loud"}, {"id": "f6", "type": "textarea", "label": "What I would tell a friend who marked the same squares"}]'::jsonb, array['perinatal and postpartum', 'group', 'support', 'play']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('good-enough-day-planner', 'Good-Enough Day Planner', 'worksheet'::resource_kind, 'A one-page plan that sets a minimum, a middle and a bonus version of the day.', 'Replace an all-or-nothing day with a flexible version a tired parent can meet.', array['Adults']::text[], '20 minutes', 'Fill it out together using a typical tough day. Many new parents grade themselves against an imagined perfect day, so help your client name a true minimum that still counts, such as one meal, one shower or one outside moment. Review the page next session and adjust the tiers, since needs change quickly with a baby.', '[{"id": "f0", "type": "textarea", "label": "The things that must happen on a hard day, the true minimum"}, {"id": "f1", "type": "textarea", "label": "A realistic middle version of a day"}, {"id": "f2", "type": "textarea", "label": "Bonus items that are nice but never required"}, {"id": "f3", "type": "textarea", "label": "What I tell myself when I only manage the minimum"}, {"id": "f4", "type": "textarea", "label": "What I will say to myself instead"}, {"id": "f5", "type": "textarea", "label": "One thing I will let go of for now"}, {"id": "f6", "type": "textarea", "label": "Who can cover one item if I need it"}]'::jsonb, array['perinatal and postpartum', 'routines', 'self-compassion']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('worth-without-doing-more-thought-record', 'Worth Without Doing More Record', 'cbt'::resource_kind, 'A thought record for moments when self-worth drops after a perceived mistake.', 'Test the thought that worth depends on performance and find a more balanced view.', array['Adults', 'Teens']::text[], '20 minutes', 'Choose a recent moment where your client felt small after a mistake or criticism. The key step is separating the event from the verdict they drew about themselves. Ask them to look at what they would say to a friend and what they actually did well in the same moment. Revisit the balanced thought over a week to see whether the feeling shifts.', '[{"id": "f0", "type": "textarea", "label": "What happened"}, {"id": "f1", "type": "textarea", "label": "The verdict I gave myself"}, {"id": "f2", "type": "textarea", "label": "How strongly I believed it (0 to 100)"}, {"id": "f3", "type": "textarea", "label": "Facts that support the verdict"}, {"id": "f4", "type": "textarea", "label": "Facts that do not fit the verdict"}, {"id": "f5", "type": "textarea", "label": "What I would say to a friend in this spot"}, {"id": "f6", "type": "textarea", "label": "A more balanced thought"}, {"id": "f7", "type": "textarea", "label": "How strongly I believe the original verdict now (0 to 100)"}]'::jsonb, array['self-esteem', 'thinking traps', 'core CBT']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('willing-to-be-imperfect-practice', 'Willing to Be Imperfect Practice', 'act'::resource_kind, 'A short ACT practice for making room for self-doubt while acting on what matters.', 'Help clients take a valued step without waiting for self-doubt to fade.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask your client to pick one small valued action they have delayed because they do not feel good enough. Build willingness by naming the doubt, thanking the mind for it, and taking the step with the doubt present. Keep the step small and specific, and review it next session by asking what the doubt did and what they did.', '[{"id": "f0", "type": "textarea", "label": "A valued action I have been holding back on"}, {"id": "f1", "type": "textarea", "label": "The doubt that comes with it"}, {"id": "f2", "type": "textarea", "label": "How I will name it (I am noticing the thought that...)"}, {"id": "f3", "type": "textarea", "label": "What the doubt wants me to do"}, {"id": "f4", "type": "textarea", "label": "What I would do if the doubt could come along"}, {"id": "f5", "type": "textarea", "label": "The smallest version of the step"}, {"id": "f6", "type": "textarea", "label": "When and where I will do it"}, {"id": "f7", "type": "textarea", "label": "What I noticed afterward"}]'::jsonb, array['self-esteem', 'willingness', 'core ACT']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('kind-voice-skills-card', 'Kind Voice Skills Card', 'dbt'::resource_kind, 'A DBT-style card pairing self-validation with a plan for harsh self-talk.', 'Practice speaking to yourself in a steadier, kinder voice when you feel not enough.', array['Adults', 'Teens']::text[], '20 minutes', 'Introduce validation as saying what makes sense about a feeling without agreeing it is a fact. Rehearse the card in session with a real moment of harsh self-talk and let your client hear how it lands. Some will find kindness hard at first, so keep wording plain and credible rather than glowing. Invite them to test one line at home.', '[{"id": "f0", "type": "textarea", "label": "A moment this week I was hard on myself"}, {"id": "f1", "type": "textarea", "label": "The feeling underneath"}, {"id": "f2", "type": "textarea", "label": "What makes sense about feeling that way"}, {"id": "f3", "type": "textarea", "label": "A sentence a caring friend might say"}, {"id": "f4", "type": "textarea", "label": "A skill I can use when I notice the harsh voice"}, {"id": "f5", "type": "textarea", "label": "My own words for validating myself"}, {"id": "f6", "type": "textarea", "label": "How I felt after saying them"}]'::jsonb, array['self-esteem', 'self-compassion', 'regulation']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('seeing-the-good-in-each-other', 'Seeing the Good in Each Other', 'couples'::resource_kind, 'Partners notice and name what they value in each other, and how it affects self-view.', 'Build self-esteem through appreciation shared between partners.', array['Couples']::text[], '30 minutes', 'Each partner writes appreciations privately, then reads them aloud while the other listens without deflecting. Many people brush off praise, so coach the listener to simply say thank you and notice how it feels. Afterward each partner names one thing they need to hear more often. Watch for backhanded compliments and redirect them gently.', '[{"id": "f0", "type": "textarea", "label": "Partner A: three things I value in my partner"}, {"id": "f1", "type": "textarea", "label": "Partner B: three things I value in my partner"}, {"id": "f2", "type": "textarea", "label": "Partner A: a time my partner helped me feel capable"}, {"id": "f3", "type": "textarea", "label": "Partner B: a time my partner helped me feel capable"}, {"id": "f4", "type": "textarea", "label": "Partner A: a compliment I find hard to accept"}, {"id": "f5", "type": "textarea", "label": "Partner B: a compliment I find hard to accept"}, {"id": "f6", "type": "textarea", "label": "What each of us would like to hear more often"}, {"id": "f7", "type": "textarea", "label": "One way we will notice the good this week"}]'::jsonb, array['self-esteem', 'couples', 'Gottman']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('my-proud-poster', 'My Proud Poster', 'kids'::resource_kind, 'A child decorates a poster of things they are good at, kind about and proud of.', 'Help a child collect and keep real evidence of their own strengths.', array['Children']::text[], '25 minutes', 'Give the child paper, markers and stickers to make a poster in their own style. Aim for specific, true things, not general praise, and let others add to it only if the child agrees. Ask the parent to hang it where the child sees it and to add one new thing weekly. If a child discloses harm or neglect, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Things I am good at"}, {"id": "f1", "type": "textarea", "label": "Times I was kind"}, {"id": "f2", "type": "textarea", "label": "Something hard I did anyway"}, {"id": "f3", "type": "textarea", "label": "What my friends or family like about me"}, {"id": "f4", "type": "textarea", "label": "A picture of me doing something I love"}, {"id": "f5", "type": "textarea", "label": "What my parent will add to my poster (parent fills in)"}, {"id": "f6", "type": "textarea", "label": "What I will do when I feel not good enough"}]'::jsonb, array['self-esteem', 'children', 'play']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('one-small-hello-game', 'One Small Hello Game', 'game'::resource_kind, 'A card game of tiny social steps, played in turns with a debrief.', 'Make small social approaches feel doable and a little playful.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Write small social actions on cards, such as making eye contact, saying hello, or asking a question. Players draw in turns, rate their nerves from 0 to 10, and try the action with the group or clinician. Use a pass card once per player. Debrief on what happened versus what was predicted, and encourage repeating the same card until the nerves ease.', '[{"id": "f0", "type": "textarea", "label": "Cards I added to the deck"}, {"id": "f1", "type": "textarea", "label": "The card I drew first and my nerves (0 to 10)"}, {"id": "f2", "type": "textarea", "label": "What I predicted would happen"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "Nerves after trying it (0 to 10)"}, {"id": "f5", "type": "textarea", "label": "The card I would like to repeat"}, {"id": "f6", "type": "textarea", "label": "What I noticed about other players"}]'::jsonb, array['social anxiety', 'exposure', 'group', 'play']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('after-the-event-reality-check', 'After the Event Reality Check', 'worksheet'::resource_kind, 'A page for reviewing a social event with facts instead of replaying every flaw.', 'Replace post-event replay with a fair, balanced summary of what happened.', array['Adults', 'Teens']::text[], '20 minutes', 'Use it within a day of a social event. Clients tend to recall every awkward moment and few neutral ones, so ask them to separate what was observable from what they inferred about others'' thoughts. The aim is a short, fair summary, not a positive spin. Review the pattern over several events.', '[{"id": "f0", "type": "textarea", "label": "The event and who was there"}, {"id": "f1", "type": "textarea", "label": "What I remember going wrong"}, {"id": "f2", "type": "textarea", "label": "What I actually know happened, facts only"}, {"id": "f3", "type": "textarea", "label": "What I assumed others thought"}, {"id": "f4", "type": "textarea", "label": "Evidence that others noticed or did not notice"}, {"id": "f5", "type": "textarea", "label": "Things that went fine or neutral"}, {"id": "f6", "type": "textarea", "label": "A fair summary in two sentences"}, {"id": "f7", "type": "textarea", "label": "What I will do with the replay when it starts"}]'::jsonb, array['social anxiety', 'rumination', 'evidence']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('worst-case-scenario-ladder', 'Worst Case Scenario Ladder', 'cbt'::resource_kind, 'A ladder that unpacks the feared social outcome and checks what would really follow.', 'Examine feared social outcomes and how likely and how survivable they are.', array['Adults', 'Teens']::text[], '25 minutes', 'Walk your client down the ladder with a specific upcoming situation. Ask what would happen, then what would that mean, and so on, until the core fear is visible. Then work back up, asking how likely each step is and how they would cope. This works best when the fear is concrete, so keep pressing for details.', '[{"id": "f0", "type": "textarea", "label": "The situation I am dreading"}, {"id": "f1", "type": "textarea", "label": "The worst thing I think could happen"}, {"id": "f2", "type": "textarea", "label": "If that happened, what would it mean about me"}, {"id": "f3", "type": "textarea", "label": "What I fear would follow after that"}, {"id": "f4", "type": "textarea", "label": "How likely each step is (0 to 100)"}, {"id": "f5", "type": "textarea", "label": "How I would cope if it did happen"}, {"id": "f6", "type": "textarea", "label": "What I can try to test the prediction"}]'::jsonb, array['social anxiety', 'core CBT', 'behavioral experiment']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('social-values-compass', 'Social Values Compass', 'act'::resource_kind, 'A values exercise connecting social effort to what the client wants for their relationships.', 'Link social discomfort to what matters so effort has a purpose.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask your client what kind of friend, partner or colleague they want to be, then link it to small social actions. The point is that discomfort can come along while they move toward what they care about. Avoid framing it as getting rid of nerves, and ask them to choose one action that fits a value, not a performance goal.', '[{"id": "f0", "type": "textarea", "label": "The kind of person I want to be around others"}, {"id": "f1", "type": "textarea", "label": "A relationship I want to grow"}, {"id": "f2", "type": "textarea", "label": "What anxiety says when I move toward it"}, {"id": "f3", "type": "textarea", "label": "What I do instead when anxiety is loud"}, {"id": "f4", "type": "textarea", "label": "A small action that fits my value"}, {"id": "f5", "type": "textarea", "label": "The discomfort I am willing to carry"}, {"id": "f6", "type": "textarea", "label": "When I will take the step"}, {"id": "f7", "type": "textarea", "label": "What I noticed afterward"}]'::jsonb, array['social anxiety', 'values', 'core ACT']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('calm-body-before-people-card', 'Calm Body Before People Card', 'dbt'::resource_kind, 'A DBT skills card for settling the body before and during a social event.', 'Use distress tolerance skills to steady a racing body in social moments.', array['Adults', 'Teens']::text[], '20 minutes', 'Practice the skills in session before your client tries them in the wild, since new skills rarely work first try under pressure. Offer a few options such as paced breathing, cold water on the hands, and a grounding look around the room, and let them choose. Ask them to rate their body before and after to see what helps.', '[{"id": "f0", "type": "textarea", "label": "A social situation that makes my body react"}, {"id": "f1", "type": "textarea", "label": "Signs in my body I notice first"}, {"id": "f2", "type": "textarea", "label": "Distress level before (0 to 10)"}, {"id": "f3", "type": "textarea", "label": "The skill I chose from the list"}, {"id": "f4", "type": "textarea", "label": "What I did, step by step"}, {"id": "f5", "type": "textarea", "label": "Distress level after (0 to 10)"}, {"id": "f6", "type": "textarea", "label": "What I would change next time"}, {"id": "f7", "type": "textarea", "label": "Where I will keep this card"}]'::jsonb, array['social anxiety', 'distress tolerance', 'skills']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('anniversary-plan-for-two', 'Anniversary Plan for Two', 'couples'::resource_kind, 'A shared plan for a hard date, with each partner naming what they need and what they can offer.', 'Help two grieving partners plan a difficult date without leaving either one alone with it.', array['Couples']::text[], '30 minutes', 'Partners often grieve a shared loss on different timelines and guess at what the other wants on a hard date. Have each partner fill in their own side first, then compare. Notice where one wants company and the other wants space, and help them build a plan that holds both. Revisit it after the date.', '[{"id": "f0", "type": "textarea", "label": "Date or season we are planning for"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I hope this day looks like"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I hope this day looks like"}, {"id": "f3", "type": "textarea", "label": "Partner A: one thing I need from you that day"}, {"id": "f4", "type": "textarea", "label": "Partner B: one thing I need from you that day"}, {"id": "f5", "type": "textarea", "label": "Something we will do together"}, {"id": "f6", "type": "textarea", "label": "Something each of us may do alone, and how we will check in"}, {"id": "f7", "type": "textarea", "label": "How we will know if one of us needs to change the plan"}]'::jsonb, array['grief and loss', 'couples', 'planning']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('our-family-remembering-tree', 'Our Family Remembering Tree', 'kids'::resource_kind, 'A drawn tree where a child adds leaves for memories, feelings and questions about someone who died.', 'Give a grieving child a drawn, hands-on way to hold memories and questions alongside a caregiver.', array['Children']::text[], '30 minutes', 'Give the child paper and colored pencils and draw a bare tree together. Each leaf holds a memory, a feeling or a question, and the child decides what goes on it. The parent sits alongside, listens, and adds a leaf of their own without correcting anything. If a child discloses harm or abuse while drawing, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw the tree and write the name of the person we are remembering"}, {"id": "f1", "type": "textarea", "label": "Draw three leaves for happy memories"}, {"id": "f2", "type": "textarea", "label": "Draw a leaf for a hard feeling and give it a color"}, {"id": "f3", "type": "textarea", "label": "Draw a leaf for a question I still have"}, {"id": "f4", "type": "textarea", "label": "Parent: a leaf with one memory of your own to share"}, {"id": "f5", "type": "textarea", "label": "Where we will keep the tree and when we will add more leaves"}]'::jsonb, array['grief and loss', 'children', 'art']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('memory-lane-turns-game', 'Memory Lane Turns Game', 'game'::resource_kind, 'A turn-taking card game where players share stories and feelings about someone who died.', 'Make it easier for family members to talk about a loss by taking small, chosen turns.', array['Children', 'Adults', 'Groups']::text[], '40 minutes', 'Players take turns drawing a prompt card and may share, pass, or swap with the next player; passing is always allowed. Write the cards together with the group in advance, mixing light memories with harder ones. Keep the pace slow and close with a debrief on what it was like to hear each other. Watch for the quiet player who passes every turn.', '[{"id": "f0", "type": "textarea", "label": "Rules we all agree on before we start"}, {"id": "f1", "type": "textarea", "label": "Prompt cards I want to add: a favorite memory"}, {"id": "f2", "type": "textarea", "label": "Prompt cards I want to add: something I miss"}, {"id": "f3", "type": "textarea", "label": "Prompt cards I want to add: something I wish I could say"}, {"id": "f4", "type": "textarea", "label": "One thing I heard from someone else that stayed with me"}, {"id": "f5", "type": "textarea", "label": "How my body felt during the game"}, {"id": "f6", "type": "textarea", "label": "What I want to do differently with these stories after today"}]'::jsonb, array['grief and loss', 'play', 'family']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('loss-ripple-effects-sheet', 'Loss Ripple Effects Sheet', 'worksheet'::resource_kind, 'A page for tracing how a loss touches routines, roles, relationships and plans beyond the sadness.', 'Show a client the secondary changes a loss brings so they can name what else needs attention.', array['Adults', 'Teens']::text[], '30 minutes', 'Grief is often reduced to sadness, yet clients describe losing roles, routines and a future they had pictured. Use the sheet to make those ripples visible so you can sort them into what needs grieving, what needs practical help, and what can wait. Expect some clients to find one area much heavier than the rest.', '[{"id": "f0", "type": "textarea", "label": "The loss, in a sentence"}, {"id": "f1", "type": "textarea", "label": "Daily routines that changed"}, {"id": "f2", "type": "textarea", "label": "Roles I held that are different now"}, {"id": "f3", "type": "textarea", "label": "Relationships that shifted"}, {"id": "f4", "type": "textarea", "label": "Plans or hopes for the future that changed"}, {"id": "f5", "type": "textarea", "label": "Practical tasks that piled up"}, {"id": "f6", "type": "textarea", "label": "Which ripple weighs most right now"}, {"id": "f7", "type": "textarea", "label": "Who could help with one of these this week"}]'::jsonb, array['grief and loss', 'roles', 'secondary losses']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('what-grief-tells-me-record', 'What Grief Tells Me Record', 'cbt'::resource_kind, 'A thought record for grief that separates painful but accurate thoughts from ones that add extra weight.', 'Help a client tell apart the thoughts that fit the loss from the ones that deepen distress.', array['Adults', 'Teens']::text[], '25 minutes', 'Unlike a standard thought record, this one does not try to talk anyone out of sadness. Clients mark which thoughts are true and painful, and look more closely at the ones phrased as absolutes, such as never or always. Go gently, as some thoughts that look like traps are part of honoring the person. Let the client choose which to keep.', '[{"id": "f0", "type": "textarea", "label": "The moment grief hit hard"}, {"id": "f1", "type": "textarea", "label": "The thought that came with it"}, {"id": "f2", "type": "textarea", "label": "Feeling and how strong it was, 0 to 100"}, {"id": "f3", "type": "textarea", "label": "Is this thought true and painful, or does it add extra weight"}, {"id": "f4", "type": "textarea", "label": "Evidence that fits the thought"}, {"id": "f5", "type": "textarea", "label": "Words like always or never in the thought"}, {"id": "f6", "type": "textarea", "label": "A kinder version that still honors the loss"}, {"id": "f7", "type": "textarea", "label": "How I feel after rewriting it"}]'::jsonb, array['grief and loss', 'core CBT', 'thinking traps']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('relationship-values-gap-sheet', 'Relationship Values Gap Sheet', 'act'::resource_kind, 'Compares the partner a client wants to be with what they actually did this week, without blame.', 'Help a client notice the gap between valued relationship actions and recent choices, then pick one step.', array['Adults']::text[], '25 minutes', 'This is a values-and-committed-action tool for a client working on their own side of a relationship. Keep the focus on chosen actions, not on the partner''s behavior. Expect some clients to turn the gap into a verdict on themselves, so go back to what they care about. Pick one small action they can take this week.', '[{"id": "f0", "type": "textarea", "label": "The kind of partner I want to be"}, {"id": "f1", "type": "textarea", "label": "A moment this week that matched it"}, {"id": "f2", "type": "textarea", "label": "A moment this week that did not match"}, {"id": "f3", "type": "textarea", "label": "What got in the way: thoughts, feelings, urges"}, {"id": "f4", "type": "textarea", "label": "A willing stance toward those feelings"}, {"id": "f5", "type": "textarea", "label": "One small action I will take this week"}, {"id": "f6", "type": "textarea", "label": "How I will notice I did it"}]'::jsonb, array['relationship issues', 'core ACT', 'values']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('interpersonal-effectiveness-plan', 'Interpersonal Effectiveness Plan', 'dbt'::resource_kind, 'Plans a hard conversation using DEAR MAN, GIVE and FAST steps, with a rehearsal line for each.', 'Help a client prepare a specific request or boundary with a partner using interpersonal skills.', array['Adults', 'Teens']::text[], '30 minutes', 'Choose one real conversation the client wants to have. Work through DEAR MAN for the request, then GIVE for keeping the relationship intact and FAST for self-respect, and rehearse the opening lines aloud in session. Clients often skip the Mindful step and drift to other topics, so practice repeating the ask calmly.', '[{"id": "f0", "type": "textarea", "label": "The situation and who it is with"}, {"id": "f1", "type": "textarea", "label": "Describe: the facts only"}, {"id": "f2", "type": "textarea", "label": "Express: how I feel about it"}, {"id": "f3", "type": "textarea", "label": "Assert: what I am asking for"}, {"id": "f4", "type": "textarea", "label": "Reinforce: what is good for both of us"}, {"id": "f5", "type": "textarea", "label": "Gentle, interested, easy: how I will keep the tone"}, {"id": "f6", "type": "textarea", "label": "Fair and truthful: what I will not say or do"}, {"id": "f7", "type": "textarea", "label": "Rehearsal: my first two sentences"}]'::jsonb, array['relationship issues', 'interpersonal effectiveness', 'communication']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('daily-appreciation-and-ask-sheet', 'Daily Appreciation and Ask Sheet', 'couples'::resource_kind, 'A short shared sheet where each partner offers one appreciation and one small ask each day.', 'Build a daily habit of noticing the good and making clear, small requests between two partners.', array['Couples']::text[], 'Five minutes daily for two weeks', 'Each partner completes their own side once a day and shares it at a set time. Appreciations must be specific, and asks must be small, positive and doable that day. Watch for asks that are criticisms in disguise. Review the pattern together at the next session, and note what each partner learned from the other''s answers.', '[{"id": "f0", "type": "textarea", "label": "Partner A: something I appreciated about you today"}, {"id": "f1", "type": "textarea", "label": "Partner A: one small thing I would like tomorrow"}, {"id": "f2", "type": "textarea", "label": "Partner B: something I appreciated about you today"}, {"id": "f3", "type": "textarea", "label": "Partner B: one small thing I would like tomorrow"}, {"id": "f4", "type": "textarea", "label": "What I did with the other''s ask"}, {"id": "f5", "type": "textarea", "label": "What was hard about doing this"}, {"id": "f6", "type": "textarea", "label": "What we will keep"}]'::jsonb, array['relationship issues', 'couples', 'appreciation']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('home-of-our-family-drawing', 'Home of Our Family Drawing', 'kids'::resource_kind, 'A drawing activity where a child shows who lives in the family home and how each person feels.', 'Let a child show how they see the relationships at home without needing the words for it.', array['Children']::text[], '30 minutes', 'Ask the child to draw the house, put each family member in a room, and add a color for each person''s feelings. The parent watches and listens without correcting the picture, and later can add a room of their own. Treat the drawing as the child''s view, not a fact. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw your house and the people in it"}, {"id": "f1", "type": "textarea", "label": "Pick a color for how each person feels most days"}, {"id": "f2", "type": "textarea", "label": "Draw where you like to be most"}, {"id": "f3", "type": "textarea", "label": "Draw one thing you wish was different at home"}, {"id": "f4", "type": "textarea", "label": "Draw something that helps when people are upset"}, {"id": "f5", "type": "textarea", "label": "Parent: one thing you heard from the drawing"}]'::jsonb, array['relationship issues', 'children', 'family']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('fair-fight-referee-game', 'Fair Fight Referee Game', 'game'::resource_kind, 'A role-play game where partners practice a disagreement while a referee flags rule breaks.', 'Give couples a low-stakes way to practice fair argument rules and notice their own habits.', array['Couples', 'Groups']::text[], '45 minutes', 'Set rules together: no name-calling, one person talks at a time, a time-out is always allowed. Partners argue a mild, made-up topic while a referee, you or a second pair, flags rule breaks with a card. Swap roles each round, then debrief on what each person noticed. Keep it light and stop the game if a real conflict surfaces.', '[{"id": "f0", "type": "textarea", "label": "Our agreed rules for a fair fight"}, {"id": "f1", "type": "textarea", "label": "The mild topic we picked"}, {"id": "f2", "type": "textarea", "label": "A rule I broke"}, {"id": "f3", "type": "textarea", "label": "A rule my partner kept well"}, {"id": "f4", "type": "textarea", "label": "What the referee noticed"}, {"id": "f5", "type": "textarea", "label": "What I felt in my body when I was flagged"}, {"id": "f6", "type": "textarea", "label": "One rule I want us to use at home"}]'::jsonb, array['relationship issues', 'play', 'conflict']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('window-of-comfort-map', 'Window of Comfort Map', 'worksheet'::resource_kind, 'A page for mapping what feels settled, too activated or too numb, with grounding steps for each.', 'Help a client recognize their own states and choose a stabilizing step without revisiting what happened.', array['Adults', 'Teens']::text[], '30 minutes', 'This stays in the present: clients map how their body and mind feel when settled, wound up or shut down, and which steps help. Never ask for details of what happened. Let the client choose the pace and skip any box. Practice one grounding step in session so it is familiar before they need it at home.', '[{"id": "f0", "type": "textarea", "label": "What feeling settled is like for me"}, {"id": "f1", "type": "textarea", "label": "Signs I am getting wound up"}, {"id": "f2", "type": "textarea", "label": "Signs I am shutting down"}, {"id": "f3", "type": "textarea", "label": "Something that helps when I am wound up"}, {"id": "f4", "type": "textarea", "label": "Something that helps when I am shut down"}, {"id": "f5", "type": "textarea", "label": "A person or place that feels safe"}, {"id": "f6", "type": "textarea", "label": "The step I will try this week"}]'::jsonb, array['sexual abuse', 'grounding', 'stabilization']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('safe-present-thought-check', 'Safe Present Thought Check', 'cbt'::resource_kind, 'A thought record for here-and-now moments when old fear shows up in a safe setting.', 'Help a client check the present moment against a fear that arrives unannounced.', array['Adults', 'Teens']::text[], '25 minutes', 'This record covers only the present moment: where the client is, who is there, and what is different now. It never asks about the past event. Look for thoughts that treat the present as the past, and let the client lead on which ones to examine. Stop and ground first if a memory begins to take over.', '[{"id": "f0", "type": "textarea", "label": "Where I am right now"}, {"id": "f1", "type": "textarea", "label": "What set off the feeling"}, {"id": "f2", "type": "textarea", "label": "The thought that came with it"}, {"id": "f3", "type": "textarea", "label": "How strong the feeling was, 0 to 100"}, {"id": "f4", "type": "textarea", "label": "What I can see, hear and touch around me"}, {"id": "f5", "type": "textarea", "label": "What is different about now"}, {"id": "f6", "type": "textarea", "label": "A thought that fits the present"}, {"id": "f7", "type": "textarea", "label": "How strong the feeling is now"}]'::jsonb, array['sexual abuse', 'core CBT', 'safety']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('self-kindness-pause-practice', 'Self-Kindness Pause Practice', 'act'::resource_kind, 'A short pause for responding to harsh self-talk with kindness, with room to notice and let thoughts pass.', 'Help a client meet shame-filled self-talk with distance and kindness, and then take a small caring action.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients may carry harsh thoughts about themselves that are not about what happened but about who they are. Introduce a pause: notice the thought, name it as a thought, and offer yourself what you would offer a friend. Choose a gentle phrase together in session. Do not push; the client decides how close to get.', '[{"id": "f0", "type": "textarea", "label": "A harsh thought I had about myself"}, {"id": "f1", "type": "textarea", "label": "Notice it: I am having the thought that..."}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend who thought this"}, {"id": "f3", "type": "textarea", "label": "A kind phrase I can use"}, {"id": "f4", "type": "textarea", "label": "Where I feel the kindness in my body"}, {"id": "f5", "type": "textarea", "label": "A small caring action I can do today"}, {"id": "f6", "type": "textarea", "label": "Who I can share this practice with"}]'::jsonb, array['sexual abuse', 'self-compassion', 'core ACT']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('self-soothe-kit-builder', 'Self-Soothe Kit Builder', 'dbt'::resource_kind, 'Builds a personal kit of soothing options for each of the five senses to use when feeling overwhelmed.', 'Help a client assemble ready-to-use sensory soothing options for hard moments.', array['Adults', 'Teens']::text[], '30 minutes', 'Work through each sense and have the client test options in session: a scent, a texture, a sound, a taste, something to look at. Choose items that are safe and truly soothing for them, not what they think they should like. Some sensory items can be unexpected triggers, so let them drop any that are. Check in on what they actually try.', '[{"id": "f0", "type": "textarea", "label": "Something I can look at that calms me"}, {"id": "f1", "type": "textarea", "label": "A sound that settles me"}, {"id": "f2", "type": "textarea", "label": "A scent I find comforting"}, {"id": "f3", "type": "textarea", "label": "A taste I enjoy"}, {"id": "f4", "type": "textarea", "label": "A texture or touch that feels safe"}, {"id": "f5", "type": "textarea", "label": "Where I will keep my kit"}, {"id": "f6", "type": "textarea", "label": "When I will try it this week"}, {"id": "f7", "type": "textarea", "label": "What I noticed when I tried it"}]'::jsonb, array['sexual abuse', 'distress tolerance', 'self-soothing']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('partner-pacing-agreement', 'Partner Pacing Agreement for Support', 'couples'::resource_kind, 'A partner-pacing tool where one partner sets the pace of closeness and the other offers steady support.', 'Help partners agree on a pace, a stop signal and a way to reconnect, without discussing what happened.', array['Couples']::text[], '30 minutes', 'This is about pacing and safety in the present. The partner who is a survivor decides what feels comfortable, and the supportive partner commits to following that pace. Neither partner shares details of what happened. Agree on a stop signal and a way to reconnect afterward, and revisit the agreement as things change.', '[{"id": "f0", "type": "textarea", "label": "Survivor partner: things that help me feel safe near you"}, {"id": "f1", "type": "textarea", "label": "Survivor partner: our stop signal"}, {"id": "f2", "type": "textarea", "label": "Supportive partner: how I will follow your pace"}, {"id": "f3", "type": "textarea", "label": "Supportive partner: how I will respond when you use the signal"}, {"id": "f4", "type": "textarea", "label": "How we will reconnect after a pause"}, {"id": "f5", "type": "textarea", "label": "What we will do when we disagree about the pace"}, {"id": "f6", "type": "textarea", "label": "When we will review this agreement"}]'::jsonb, array['sexual abuse', 'couples', 'pacing', 'support']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('coping-skills-superhero-cape-craft', 'Coping Skills Superhero Cape', 'kids'::resource_kind, 'A child decorates a paper cape with the skills that help them when feelings get big.', 'Help a child name and remember a few coping skills in a playful, wearable form.', array['Children']::text[], '30 minutes', 'Give the child a paper or felt cape shape and markers, and let them pick a hero name. Each skill earns a cape symbol: a drawn balloon for slow breaths, a heart for asking for a hug. Keep it to three or four skills. Invite the parent for the last ten minutes so the child can teach them, and tell the parent to remind, not command, when feelings rise. If a child discloses harm or abuse while drawing, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "My hero name"}, {"id": "f1", "type": "textarea", "label": "Skill one and the symbol I drew for it"}, {"id": "f2", "type": "textarea", "label": "Skill two and the symbol I drew for it"}, {"id": "f3", "type": "textarea", "label": "Skill three and the symbol I drew for it"}, {"id": "f4", "type": "textarea", "label": "When my cape helps me most"}, {"id": "f5", "type": "textarea", "label": "What my grown-up can say to remind me"}]'::jsonb, array['coping skills', 'children', 'play']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('coping-skills-weather-report-game', 'Coping Skills Weather Report', 'game'::resource_kind, 'A turn-taking game where players forecast a feeling and pick a skill to match the weather.', 'Practice matching a coping skill to the intensity of a feeling in a low-pressure group game.', array['Teens', 'Groups']::text[], '30 minutes', 'Players sit in a circle with a deck of skill cards and a pile of weather cards (drizzle, thunderstorm, fog, heat wave). On a turn, draw a weather card, say what kind of moment it stands for, and choose a skill card from the table that fits; the group votes thumbs up or down, and one point goes to a good match. Play ten minutes, then debrief on which skills fit which weather. Let passing be allowed so nobody is cornered.', '[{"id": "f0", "type": "textarea", "label": "The weather card I drew and the moment it stood for"}, {"id": "f1", "type": "textarea", "label": "The skill I chose and why it fit"}, {"id": "f2", "type": "textarea", "label": "A skill the group picked that I would not have thought of"}, {"id": "f3", "type": "textarea", "label": "A weather type where I still lack a good skill"}, {"id": "f4", "type": "textarea", "label": "One skill I will try this week and when"}]'::jsonb, array['coping skills', 'play', 'group']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('coping-skills-first-ten-minutes-plan', 'First Ten Minutes Plan', 'worksheet'::resource_kind, 'A short plan for what to do in the first ten minutes after a hard moment begins.', 'Give a client a pre-decided sequence of small steps for the early minutes of distress.', array['Adults', 'Teens']::text[], '20 minutes', 'The first minutes often decide whether a hard moment grows, so build the plan when the client is calm. Ask for steps small enough to do while upset: moving rooms, cold water, one text to a person. Rehearse the first step aloud in session. Clients tend to write ambitious plans, so trim anything that needs equipment or a good mood. Review after a week and swap out whatever they skipped.', '[{"id": "f0", "type": "textarea", "label": "A moment that tends to start a rough stretch"}, {"id": "f1", "type": "textarea", "label": "The first sign that it is starting"}, {"id": "f2", "type": "textarea", "label": "Minute one to two: what I do"}, {"id": "f3", "type": "textarea", "label": "Minute three to five: what I do"}, {"id": "f4", "type": "textarea", "label": "Minute six to ten: what I do"}, {"id": "f5", "type": "textarea", "label": "Who I can contact if the ten minutes are not enough"}, {"id": "f6", "type": "textarea", "label": "What I will check on after the ten minutes pass"}]'::jsonb, array['coping skills', 'planning', 'regulation']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('coping-thought-swap-cards', 'Coping Thought Swap Cards', 'cbt'::resource_kind, 'A thought record variation where an unhelpful thought is swapped for a more balanced one.', 'Help a client notice an unhelpful thought and build a balanced alternative they can reach for.', array['Adults', 'Teens']::text[], '25 minutes', 'Use this after the client knows what a thinking trap is. They copy a thought from a hard moment onto one side of a card, then work out evidence for and against it, and write a balanced version on the other side. The card is meant to fit in a pocket. Watch for swaps that are forced positivity; the balanced thought should feel believable at a four or five out of ten, not perfect. Stack the cards over weeks.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "The thought that came up"}, {"id": "f2", "type": "textarea", "label": "How strongly I believed it, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "Evidence that supports it"}, {"id": "f4", "type": "textarea", "label": "Evidence that does not fully fit it"}, {"id": "f5", "type": "textarea", "label": "A more balanced version I can believe"}, {"id": "f6", "type": "textarea", "label": "How I feel after reading the balanced version"}]'::jsonb, array['coping skills', 'core CBT', 'thinking traps']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('coping-skills-willing-to-feel-practice', 'Making Room While Coping', 'act'::resource_kind, 'Separates skills that make room for a feeling from skills that push it away.', 'Help a client choose coping steps that move them toward what matters while the feeling stays present.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to recall a recent hard moment and list what they did. Then sort each action by whether it made room for the feeling and let them act on a value, or pushed the feeling away. Neither side is bad; the point is to see the pattern. Expect some clients to hear this as being told to just feel it. Name that making room is a choice with a purpose, and plan one small, values-linked action with the feeling coming along.', '[{"id": "f0", "type": "textarea", "label": "A hard moment and the feeling in it"}, {"id": "f1", "type": "textarea", "label": "What I did, listed in order"}, {"id": "f2", "type": "textarea", "label": "Which actions pushed the feeling away"}, {"id": "f3", "type": "textarea", "label": "Which actions made room for it"}, {"id": "f4", "type": "textarea", "label": "What mattered to me in that moment"}, {"id": "f5", "type": "textarea", "label": "One small step I could take with the feeling still there"}, {"id": "f6", "type": "textarea", "label": "How I will know I made room"}]'::jsonb, array['coping skills', 'core ACT', 'willingness', 'values']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('phobia-calm-scale-distress-card', 'Calm Scale Distress Card', 'dbt'::resource_kind, 'A card for rating distress and choosing a distress tolerance skill while facing a feared thing.', 'Pair each step toward a feared thing with a skill that helps the client stay with the distress.', array['Adults', 'Teens']::text[], '20 minutes', 'Fill this in before an approach step, then use it during and after. The client picks one or two skills from the distress tolerance set, such as paced breathing, temperature change or a grounding scan, and rates distress before, during and after. Many clients forget to rate the after number, which is where they see it settle. Practice the skill in the office first so they are not meeting it for the first time at the peak.', '[{"id": "f0", "type": "textarea", "label": "The step I plan to take toward the feared thing"}, {"id": "f1", "type": "textarea", "label": "My distress before, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "The skill I will use to stay with it"}, {"id": "f3", "type": "textarea", "label": "My distress at the highest point"}, {"id": "f4", "type": "textarea", "label": "What I told myself to keep going"}, {"id": "f5", "type": "textarea", "label": "My distress after, 0 to 10"}, {"id": "f6", "type": "textarea", "label": "What I noticed about how the number moved"}]'::jsonb, array['phobias', 'distress tolerance', 'exposure']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('phobia-partner-coach-and-step-back-plan', 'Coach and Step Back Plan', 'couples'::resource_kind, 'Both partners agree when to coach and when to step back during one partner''s brave steps.', 'Clarify what the supporting partner does and does not do while the other faces a feared thing.', array['Couples']::text[], '30 minutes', 'Have both partners fill in their own half before comparing. The partner facing the fear says what helps and what pulls them back; the supporting partner names the urge to rescue or push and what they will do instead. Agree on a signal for a pause. Couples often drift into reassuring or taking over, so ask each to describe the other''s part in their own words, and set a check-in time after each step to talk about how it went.', '[{"id": "f0", "type": "textarea", "label": "Partner facing the fear: the step I am taking"}, {"id": "f1", "type": "textarea", "label": "Partner facing the fear: what helps me most from you"}, {"id": "f2", "type": "textarea", "label": "Partner facing the fear: what does not help"}, {"id": "f3", "type": "textarea", "label": "Supporting partner: how I will coach during the step"}, {"id": "f4", "type": "textarea", "label": "Supporting partner: what I will not do, such as rescuing or hurrying"}, {"id": "f5", "type": "textarea", "label": "Our pause signal and what we do when we use it"}, {"id": "f6", "type": "textarea", "label": "When we will check in and what each of us will say"}]'::jsonb, array['phobias', 'couples', 'support']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('phobia-brave-explorer-map-for-kids', 'Brave Explorer Treasure Map', 'kids'::resource_kind, 'A child draws a treasure map where each landmark is a small step toward a feared thing.', 'Help a child see approaching a fear as an adventure made of small, doable steps.', array['Children']::text[], '30 minutes', 'Let the child draw an island with a start flag and a treasure at the far end, then add three to five landmarks that are steps toward the feared thing, easy ones first. They choose a stamp or sticker for each landmark reached. Tell the parent to praise the trying, stay calm, and avoid pushing past the step the child picked. Do not use the map to force a step. If a child discloses anything worrying while drawing, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "What the treasure at the end of the map is"}, {"id": "f1", "type": "textarea", "label": "Landmark one, the easiest step"}, {"id": "f2", "type": "textarea", "label": "Landmark two"}, {"id": "f3", "type": "textarea", "label": "Landmark three"}, {"id": "f4", "type": "textarea", "label": "Landmark four, the hardest step"}, {"id": "f5", "type": "textarea", "label": "How my grown-up helps on the trip"}, {"id": "f6", "type": "textarea", "label": "The stamp I will give myself for each step"}]'::jsonb, array['phobias', 'children', 'exposure', 'play']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('phobia-fear-forecast-dice-game', 'Fear Forecast Dice Game', 'game'::resource_kind, 'A dice game where players guess how a feared situation will go, then compare with what happened.', 'Practice noticing the gap between feared predictions and real outcomes in a playful, shared setting.', array['Teens', 'Groups']::text[], '30 minutes', 'Each player names a mild, not a top-rated, situation they have tried or could try. Before acting or recalling the outcome, they roll a die to set their predicted scariness from one to six, then share what really happened and roll again for actual scariness. Compare the two numbers; a gap earns a point for the whole group. Debrief on which predictions ran high. Keep everyone choosing their own situations, and never dare a player to go further.', '[{"id": "f0", "type": "textarea", "label": "The situation I picked"}, {"id": "f1", "type": "textarea", "label": "My predicted scariness number"}, {"id": "f2", "type": "textarea", "label": "What I expected to happen"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "My actual scariness number"}, {"id": "f5", "type": "textarea", "label": "What the gap taught me"}, {"id": "f6", "type": "textarea", "label": "One situation I could try before our next meeting"}]'::jsonb, array['phobias', 'group', 'behavioral experiment']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('phobia-avoidance-cost-ledger', 'Fear Avoidance Give and Take Ledger', 'worksheet'::resource_kind, 'A ledger of what avoiding a feared thing costs across days, activities and relationships.', 'Help a client see what the avoidance protects and what it takes away, to inform their own choice.', array['Adults', 'Teens']::text[], '25 minutes', 'The client lists what avoidance gives them (relief, safety) and what it costs (places not visited, plans declined, energy spent planning around it). Go slowly with the cost side; some clients feel blamed. The aim is not to push but to show what is at stake so they decide what to work on. Revisit the ledger every few weeks as steps are taken, and have the client add anything that comes back into their life.', '[{"id": "f0", "type": "textarea", "label": "The thing I avoid"}, {"id": "f1", "type": "textarea", "label": "Ways I avoid it or work around it"}, {"id": "f2", "type": "textarea", "label": "What avoiding gives me in the moment"}, {"id": "f3", "type": "textarea", "label": "Places, plans or people I miss because of it"}, {"id": "f4", "type": "textarea", "label": "Time and energy I spend managing it"}, {"id": "f5", "type": "textarea", "label": "Something I would do again if the fear were smaller"}, {"id": "f6", "type": "textarea", "label": "The smallest step I would be willing to test"}]'::jsonb, array['phobias', 'avoidance', 'exposure']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('appearance-thought-reframe-practice', 'Appearance Thought Reframe', 'cbt'::resource_kind, 'A thought record for judgments about how the client looks, ending in a more balanced view.', 'Help a client catch harsh appearance thoughts and test them against what else is true.', array['Adults', 'Teens']::text[], '25 minutes', 'Start with a recent moment when an appearance thought hit hard. Name the thinking trap (mind reading, all-or-nothing, fortune telling) and then ask what a friend would say about the same thought. Clients often skip the evidence column and write a positive slogan, so hold them to what is actually observable. Do not ask for any measurements or comparisons of the body. Treat the balanced thought as one to try on, not a rule.', '[{"id": "f0", "type": "textarea", "label": "The moment and where I was"}, {"id": "f1", "type": "textarea", "label": "The appearance thought that came up"}, {"id": "f2", "type": "textarea", "label": "The feeling and how strong it was, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "The thinking trap it fits"}, {"id": "f4", "type": "textarea", "label": "What I would say to a friend with this thought"}, {"id": "f5", "type": "textarea", "label": "A more balanced thought"}, {"id": "f6", "type": "textarea", "label": "How strong the feeling is now"}]'::jsonb, array['body image', 'thinking traps', 'core CBT']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('body-image-values-over-appearance-compass', 'Values Over Appearance Compass', 'act'::resource_kind, 'A compass that points the client from appearance worries toward actions that matter to them.', 'Redirect time spent on appearance worries toward valued actions with people and activities.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask the client what appearance worries have kept them from doing, then what they would do if those worries were along for the ride. Have them name two values and a small action for each. Expect clients to want the worry gone first; gently note that the compass works with the worry present. Check back next session on whether the action happened and what the worry did while it did.', '[{"id": "f0", "type": "textarea", "label": "A moment when appearance worries took over"}, {"id": "f1", "type": "textarea", "label": "What those worries kept me from doing"}, {"id": "f2", "type": "textarea", "label": "Something I value, such as friendship or play"}, {"id": "f3", "type": "textarea", "label": "A small action for that value this week"}, {"id": "f4", "type": "textarea", "label": "A second value"}, {"id": "f5", "type": "textarea", "label": "A small action for that second value"}, {"id": "f6", "type": "textarea", "label": "What I will say to the worry when it comes along"}]'::jsonb, array['body image', 'core ACT', 'values']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('body-image-wave-surfing-after-comparison', 'Comparison Wave Skill Card', 'dbt'::resource_kind, 'A DBT skills card for riding out the pull of comparison after seeing other people online or in person.', 'Give a client a step-by-step skill for the surge of feeling after comparing their appearance to others.', array['Adults', 'Teens']::text[], '20 minutes', 'Walk the client through naming the emotion, noticing where it sits, and using opposite action or self-soothing in the moments after comparing. Many clients want to avoid every trigger, so help them choose skills that work even when avoidance fails. Practice the first two steps in session using a mild recalled example. Ask them to bring back the card with one use marked, whether or not it helped.', '[{"id": "f0", "type": "textarea", "label": "What I saw or heard that started the comparison"}, {"id": "f1", "type": "textarea", "label": "The emotion I named"}, {"id": "f2", "type": "textarea", "label": "Where I feel it in my body"}, {"id": "f3", "type": "textarea", "label": "The urge it brought, such as scrolling or hiding"}, {"id": "f4", "type": "textarea", "label": "The opposite action I could take"}, {"id": "f5", "type": "textarea", "label": "A self-soothing step I will use"}, {"id": "f6", "type": "textarea", "label": "How the feeling changed after the skill"}]'::jsonb, array['body image', 'emotion regulation', 'distress tolerance']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('partner-compliment-and-comfort-guide', 'Partner Compliment and Comfort Guide', 'couples'::resource_kind, 'Each partner says which words about appearance land well and which do not.', 'Help both partners learn what kinds of comments feel supportive when body image worries are present.', array['Couples']::text[], '30 minutes', 'Each partner completes the sheet separately, then they read their answers aloud while the other listens without fixing. The partner with body image worries says what helps and what stings; the other describes what they notice and wish they could say. Couples often default to reassurance that does not land, so look for comments about what the person does or who they are. Close by agreeing on one phrase each to try.', '[{"id": "f0", "type": "textarea", "label": "Partner with worries: comments that feel warm to me"}, {"id": "f1", "type": "textarea", "label": "Partner with worries: comments that do not help, even if kindly meant"}, {"id": "f2", "type": "textarea", "label": "Partner with worries: what I wish you would ask me"}, {"id": "f3", "type": "textarea", "label": "Supporting partner: what I want to say but hold back"}, {"id": "f4", "type": "textarea", "label": "Supporting partner: a comment about who you are that I could offer"}, {"id": "f5", "type": "textarea", "label": "What we both will try this week"}, {"id": "f6", "type": "textarea", "label": "How we will tell each other if a comment misses"}]'::jsonb, array['body image', 'couples', 'communication']::text[], '2026-10-01T15:00:00+00:00'::timestamptz),
  ('my-body-adventure-drawing-for-kids', 'My Body Adventure Drawing', 'kids'::resource_kind, 'A child draws the adventures their body takes them on and what each part helps them do.', 'Help a child connect their body to play and adventure rather than to how it looks.', array['Children']::text[], '30 minutes', 'Give the child a big sheet and ask where their body went this week: running, hugging, dancing, climbing. They draw a picture of one adventure and label what their body helped with. Keep the talk on what the body does and enjoys. Tell the parent to notice and name what the child''s body does and to avoid comments about looks for the week. If a child discloses harm or abuse, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "An adventure my body took me on"}, {"id": "f1", "type": "textarea", "label": "What my legs, hands or arms helped me do"}, {"id": "f2", "type": "textarea", "label": "A thing my body does that I am proud of"}, {"id": "f3", "type": "textarea", "label": "Something I like to do with my friends or family"}, {"id": "f4", "type": "textarea", "label": "A kind thing I can say about my body"}, {"id": "f5", "type": "textarea", "label": "What my grown-up will say when we talk about bodies"}]'::jsonb, array['body image', 'children', 'play']::text[], '2026-10-01T15:00:00+00:00'::timestamptz)
